// Per-panel car meshes (workstream R): the procedural low-poly mesh of a car
// (data/panels/meshes/<car>.json, generated by tools/assets) drawn as one Three.js mesh per part,
// every vertex skinned to its region's lattice nodes so dents show on every panel.
//
// Free panels (unlatched doors/hood/trunk, hanging bumpers/fenders) are rigid bodies in the sim:
// their lattice nodes are already rotated about the hinge. Plain displacement blending would
// smear a rotated door, so for those panels we fit the panel's rigid frame from three of its
// nodes (rest → current), take the dent in that frame and put the vertices back through it.
// Detached panels leave the car as visual debris (ballistic, bounce on the road; the physics
// debris body lives in Rapier and is not exposed to the browser yet).
//
// Mesh format 4 (tools/assets/src/mesh.rs `MESH_FORMAT`) = the detailed-car-models fields
// (format 2 there: part kinds / materials, `rigid`, `tints`, `livery`, `atlas`,
// `wheel_camber_deg`, livery atlas UVs) plus round 12's `fold` crumple binding (format 3).
// Older files simply lack the optional fields.
//
// Wheel-space parts: tire / rim / brake_disc spin (`wheelParts`, VehicleView's spin groups);
// caliper / upright steer and follow compression but do not spin (`hubParts`, the wheel pivots).
//
// Livery: paint parts with material `livery` carry atlas UVs (layout: data/panels/README.md);
// `setLivery(texture)` maps a canvas onto them, `liveryPx()` converts car space to canvas pixels,
// `?livery=grid` in the URL shows `debugLiveryTexture()` on every car. Light-bar lenses get one
// material per side (`lightbarMaterials`), flashed by render/lights.ts.
//
// Coordinates: chassis space (+X right, +Y forward, +Z up), metres. The parent VehicleView root
// is already in that frame.
import * as THREE from "three";
import { sim } from "../wasm/sim";
import { PALETTE } from "./palette";
import { buildCrease, updateCrease, type CreaseMap } from "./crease";

/** Floats per panel in wasm `panel_states()` (mirrors crates/wp_wasm PANEL_STRIDE). */
export const PANEL_STRIDE = 10;
/** Panel state codes (mirrors wp_damage::PanelState::code). */
export const PANEL_STATE = { attached: 0, unlatched: 1, hanging: 2, detached: 3 } as const;

/** Part kinds (tools/assets/src/mesh.rs `PartKind`), plus "mod" for mod parts (render/mod_parts.ts). */
export type PartKindJson =
  | "panel" | "glass" | "light" | "mirror" | "body" | "interior" | "tire" | "rim"
  | "detail" | "engine" | "suspension" | "brake_disc" | "caliper" | "upright" | "lightbar" | "decal_carrier"
  | "mod";
/** Material slots of the mesh files (tools/assets/src/mesh.rs `MaterialSlot`). */
export type MaterialJson =
  | "paint" | "glass" | "trim" | "headlight" | "taillight" | "rubber" | "metal" | "interior"
  | "livery" | "chrome" | "carbon" | "caliper" | "engine" | "lightbar_red" | "lightbar_blue"
  | "lightbar_clear" | "emissive_amber" | "grille" | "exhaust" | "rim" | "spring" | "accent" | "underglow";
/** Materials of the mesh files plus the ones only mod parts use (render/mod_parts.ts):
 * `caliperSport` / `caliperRace` brake-kit calipers (the mesh files' `caliper` is the stock
 * one, tinted per car), `steel`, `stripe`, and `carbonWeave` (bought carbon hood / trunk lid:
 * visible twill weave under a gloss coat, unlike the plain dark `carbon` trim of the mesh files). */
export type PartMaterial = MaterialJson | "steel" | "caliperSport" | "caliperRace" | "stripe" | "carbonWeave";

/** One part of data/panels/meshes/<car>.json (tools/assets/src/mesh.rs `MeshPart`). Mod parts
 * (render/mod_parts.ts) use the same shape with kind "mod". */
export interface MeshPartJson {
  name: string;
  region: string | null;
  kind: PartKindJson;
  material: PartMaterial;
  wheel?: number | null;
  /** Bound to one node with weight 255 (moves rigidly; format 4). */
  rigid?: boolean;
  positions_mm: number[];
  uvs: number[];
  indices: number[];
  skin_nodes: number[];
  skin_weights: number[];
  /** Hood / trunk lid / front fender / rear quarter crumple (format 3; tools/assets `FoldBinding`). */
  fold?: FoldJson;
}

/**
 * How a sheet panel crumples (tools/assets/src/mesh.rs `FoldBinding`, visual only): chords from
 * the fixed end (hinge row; side panel door-side row) to the leading end; the leading end follows the
 * crushed front structure (`leads`), the shortening becomes a fold along `dir`.
 */
export interface FoldJson {
  chords: [number, number][];
  /** Per chord: three front-structure nodes the leading end follows. */
  leads: [number, number, number][];
  /** Axis the chords spread along: 0 = x (lids), 2 = z (fenders). */
  across: number;
  dir: [number, number, number];
  /** Visual gain on the shortening (own chord loss or lead push, whichever is larger). */
  gain: number;
  max_m: number;
  /** Leading-edge pop once unlatched / hanging, m. */
  pop_m: number;
  /** 3 per vertex in 1/255: crease, fixed-end lift, leading-end follow. */
  weights: number[];
}

/** Lost chord length a panel absorbs before it buckles, m (mirrors tools/assets FOLD_DEAD_ZONE_M). */
const FOLD_DEAD_ZONE_M = 0.015;
/** Share of the single-tent height each lid ridge gets (FOLD_SPLIT). */
const FOLD_SPLIT = 0.7;
/** Fixed-edge lift of an unlatched lid, share of the fold height (FOLD_REAR_LIFT). */
const FOLD_REAR_LIFT = 0.45;
/** Largest leading-end pull-back, share of the chord length (FOLD_PULL_MAX). */
const FOLD_PULL_MAX = 0.5;
/** A node this close to rest (m) counts as at rest: the crumple memory clears (FOLD_REST_EPS_M). */
const FOLD_REST_EPS_M = 1e-3;
/** A light lens breaks once one of its vertices is pushed this far (m) by the crush. */
const LIGHT_BREAK_M = 0.05;

/**
 * Fold height (m, uncapped) of a sheet whose chord measured `rest` and is effectively `lost`
 * shorter: an inextensible strip pushed together rises into a tent (tools/assets `fold_height`).
 */
export function foldHeight(rest: number, lost: number): number {
  if (rest <= 1e-3) return 0;
  const l = Math.max(0, lost - FOLD_DEAD_ZONE_M);
  const k = 1 - Math.min(l / rest, 0.5);
  return 0.5 * rest * Math.sqrt(1 - k * k);
}

/** Car-space box the livery atlas maps (mesh format 4). */
export interface LiveryAtlas {
  /** Tail y, nose y (m). */
  y: [number, number];
  /** Ground z, top z (m). */
  z: [number, number];
  /** Half width (m). */
  x_half: number;
}

/** Livery hint written by the style (tools/assets/src/style.rs `LiveryHint`). */
export interface LiveryHint {
  scheme: string;
  colors: [number, number, number][];
  text: string[];
}

/** data/panels/meshes/<car>.json (`CarMesh`). Format 1 files have none of the optional fields. */
export interface CarMeshJson {
  id: string;
  lattice_id: string;
  format: number;
  tri_count: number;
  /** Per-car colours of material slots (sRGB 0–255): rim, spring, accent, caliper, underglow, paint … */
  tints?: Partial<Record<MaterialJson, [number, number, number]>>;
  livery?: LiveryHint;
  atlas?: LiveryAtlas;
  /** Visual camber per wheel (FL FR RL RR), degrees, + = top leans in. */
  wheel_camber_deg?: [number, number, number, number];
  parts: MeshPartJson[];
}

/** Wheel-space kinds that steer but do not spin (VehicleView's wheel pivots). */
const HUB_KINDS: ReadonlySet<PartKindJson> = new Set(["caliper", "upright"]);

// ------------------------------------------------------------------------------------------
// Livery atlas (layout: data/panels/README.md "Livery atlas")
// ------------------------------------------------------------------------------------------

/** Atlas band of a livery canvas. */
export type LiverySide = "left" | "right" | "top" | "front" | "rear";

const ATLAS_PAD = 0.004;
/** Band rectangles in UV space: [u0, u1, v0, v1] (v up, texture flipY = true). */
const BANDS: Record<LiverySide, [number, number, number, number]> = {
  left: [0, 0.25, 0, 0.5],
  right: [0.25, 0.5, 0, 0.5],
  top: [0, 0.5, 0.5, 0.8],
  front: [0, 0.25, 0.8, 1],
  rear: [0.25, 0.5, 0.8, 1],
};

/** Default atlas for format-1 meshes / before load (a 4.6 m × 1.9 m × 1.5 m car). */
export const DEFAULT_ATLAS: LiveryAtlas = { y: [-2.4, 2.4], z: [0, 1.75], x_half: 1.0 };

/**
 * Car space → livery UV (u, v in 0..1, v up). Arguments per side:
 * left/right: (y, z) — y forward, z up; top: (y, x); front/rear: (x, z). Metres, chassis space.
 * Mirrors tools/assets/src/mesh.rs `atlas_uv` exactly.
 */
export function liveryUv(atlas: LiveryAtlas, side: LiverySide, a: number, b: number): [number, number] {
  const clamp = (t: number) => Math.min(Math.max(t, 0), 1);
  const fy = (y: number) => clamp((y - atlas.y[0]) / (atlas.y[1] - atlas.y[0]));
  const fz = (z: number) => clamp((z - atlas.z[0]) / (atlas.z[1] - atlas.z[0]));
  const fx = (x: number) => clamp((x + atlas.x_half) / (2 * atlas.x_half));
  let s: number;
  let t: number;
  switch (side) {
    case "left": [s, t] = [1 - fy(a), fz(b)]; break; // nose at the band's left: reads front → rear
    case "right": [s, t] = [fy(a), fz(b)]; break; // tail at the band's left: reads rear → front
    case "top": [s, t] = [fy(a), 1 - fx(b)]; break; // plan view, nose right, car left at the top
    case "front": [s, t] = [1 - fx(a), fz(b)]; break; // seen from ahead
    case "rear": [s, t] = [fx(a), fz(b)]; break; // seen from behind
  }
  const [u0, u1, v0, v1] = BANDS[side];
  return [u0 + ATLAS_PAD + (u1 - u0 - 2 * ATLAS_PAD) * s, v0 + ATLAS_PAD + (v1 - v0 - 2 * ATLAS_PAD) * t];
}

/**
 * Car space → livery canvas pixel {x, y} (canvas origin top-left) for a canvas of `w` × `h`
 * pixels mapped over the whole texture (u 0..1). Arguments as `liveryUv`. Text drawn
 * left-to-right with plain `fillText` at a left/right-side anchor reads correctly from outside.
 */
export function liveryPx(
  atlas: LiveryAtlas, side: LiverySide, a: number, b: number, w: number, h: number,
): { x: number; y: number } {
  const [u, v] = liveryUv(atlas, side, a, b);
  return { x: u * w, y: (1 - v) * h };
}

/** Pixel rectangle {x, y, w, h} of an atlas band on a `w` × `h` canvas. */
export function liveryBandPx(side: LiverySide, w: number, h: number): { x: number; y: number; w: number; h: number } {
  const [u0, u1, v0, v1] = BANDS[side];
  return { x: u0 * w, y: (1 - v1) * h, w: (u1 - u0) * w, h: (v1 - v0) * h };
}

let debugLivery: THREE.CanvasTexture | null = null;

/** A labelled grid on every atlas band (to check the UV mapping): band names, FRONT arrows, 0.5 m grid. */
export function debugLiveryTexture(atlas: LiveryAtlas = DEFAULT_ATLAS): THREE.CanvasTexture {
  if (debugLivery) return debugLivery;
  const W = 2048;
  const H = 1024;
  const c = document.createElement("canvas");
  c.width = W;
  c.height = H;
  const g = c.getContext("2d")!;
  g.fillStyle = "#777";
  g.fillRect(0, 0, W, H);
  const colours: Record<LiverySide, string> = {
    left: "#c33", right: "#36c", top: "#3a3", front: "#cc3", rear: "#c3c",
  };
  for (const side of Object.keys(BANDS) as LiverySide[]) {
    const r = liveryBandPx(side, W, H);
    g.fillStyle = colours[side];
    g.fillRect(r.x, r.y, r.w, r.h);
    g.strokeStyle = "rgba(255,255,255,0.6)";
    g.lineWidth = 2;
    // 0.5 m grid in car space.
    const lines: [number, number, number, number][] = [];
    if (side === "left" || side === "right" || side === "top") {
      for (let y = Math.ceil(atlas.y[0] * 2) / 2; y <= atlas.y[1]; y += 0.5) {
        const lo = side === "top" ? -atlas.x_half : atlas.z[0];
        const hi = side === "top" ? atlas.x_half : atlas.z[1];
        lines.push([y, lo, y, hi]);
      }
    }
    if (side !== "top") {
      for (let z = 0.5; z < atlas.z[1]; z += 0.5) {
        const a0 = side === "left" || side === "right" ? atlas.y[0] : -atlas.x_half;
        const a1 = side === "left" || side === "right" ? atlas.y[1] : atlas.x_half;
        lines.push([a0, z, a1, z]);
      }
    } else {
      lines.push([atlas.y[0], 0, atlas.y[1], 0]);
    }
    for (const [a0, b0, a1, b1] of lines) {
      const p0 = liveryPx(atlas, side, a0, b0, W, H);
      const p1 = liveryPx(atlas, side, a1, b1, W, H);
      g.beginPath();
      g.moveTo(p0.x, p0.y);
      g.lineTo(p1.x, p1.y);
      g.stroke();
    }
    g.fillStyle = "#fff";
    g.font = "bold 40px sans-serif";
    g.textAlign = "center";
    g.textBaseline = "middle";
    const label = side.toUpperCase();
    // Anchors from car space: the arrow points toward the car's front on the sides / top.
    const mid = (atlas.y[0] + atlas.y[1]) / 2;
    const zMid = 0.75;
    const at =
      side === "left" || side === "right"
        ? liveryPx(atlas, side, mid, zMid, W, H)
        : side === "top"
          ? liveryPx(atlas, side, mid, 0.3, W, H)
          : liveryPx(atlas, side, 0, zMid, W, H);
    const front = side === "left" ? "◀ FRONT" : side === "right" || side === "top" ? "FRONT ▶" : "";
    g.fillText(`${label} ${front} ABC123`, at.x, at.y);
    if (side === "front" || side === "rear") {
      const l = liveryPx(atlas, side, -0.6, 0.5, W, H);
      g.font = "bold 28px sans-serif";
      g.fillText("CAR-LEFT", l.x, l.y);
    }
  }
  debugLivery = new THREE.CanvasTexture(c);
  debugLivery.colorSpace = THREE.SRGBColorSpace;
  return debugLivery;
}

/** `?livery=<value>` from the URL (`grid`: the debug atlas on every car), or null. */
export function liveryFlag(): string | null {
  try {
    return new URLSearchParams(globalThis.location?.search ?? "").get("livery");
  } catch {
    return null;
  }
}

/** sRGB 0–255 triple → THREE.Color (linear working space). */
export function rgbColour(rgb: [number, number, number], out = new THREE.Color()): THREE.Color {
  return out.setRGB(rgb[0] / 255, rgb[1] / 255, rgb[2] / 255, THREE.SRGBColorSpace);
}

// ------------------------------------------------------------------------------------------

const meshCache = new Map<string, Promise<CarMeshJson | null>>();
/** Meshes that finished loading (null = file missing), so a new car builds on its first frame. */
const meshLoaded = new Map<string, CarMeshJson | null>();
/** Fetch + parse time per car mesh, ms (`performance.now()` stamps), for the HUD / e2e. */
export const meshTimings = new Map<string, { start: number; end: number | null; ok: boolean }>();

/** Fetch (once per car) a car's panel mesh; null if the file is missing. */
export function loadCarMesh(carId: string): Promise<CarMeshJson | null> {
  let p = meshCache.get(carId);
  if (!p) {
    const timing = { start: performance.now(), end: null as number | null, ok: false };
    meshTimings.set(carId, timing);
    p = fetch(`data/panels/meshes/${carId}.json`)
      .then((r) => (r.ok ? (r.json() as Promise<CarMeshJson>) : null))
      .catch(() => null)
      .then((m) => {
        meshLoaded.set(carId, m);
        timing.end = performance.now();
        timing.ok = m !== null;
        return m;
      });
    meshCache.set(carId, p);
  }
  return p;
}

/** A car's mesh if it has already loaded (undefined while loading or never requested). */
export function carMeshNow(carId: string): CarMeshJson | null | undefined {
  return meshLoaded.get(carId);
}

const midCache = new Map<string, Promise<CarMeshJson | null>>();
/** Mid-LOD meshes that finished loading (null = file missing: draw the full mesh instead). */
const midLoaded = new Map<string, CarMeshJson | null>();

/**
 * Fetch (once per car) a car's mid level of detail, `data/panels/meshes/mid/<car>.json`
 * (tools/assets `gen-car-mesh`, `Lod::Mid`): the same style, livery atlas, atlas UVs and tints
 * as the full mesh at ~3–6k triangles, without skin bindings. The instanced fleet and parked
 * cars draw it undeformed (render/fleet.ts, props.ts); VehicleViews always use the full mesh.
 * Resolves to the full mesh when the mid file is missing (older data), null when neither exists.
 */
export function loadCarMidMesh(carId: string): Promise<CarMeshJson | null> {
  let p = midCache.get(carId);
  if (!p) {
    p = fetch(`data/panels/meshes/mid/${carId}.json`)
      .then((r) => (r.ok ? (r.json() as Promise<CarMeshJson>) : null))
      .catch(() => null)
      .then((m) => m ?? loadCarMesh(carId))
      .then((m) => {
        midLoaded.set(carId, m);
        return m;
      });
    midCache.set(carId, p);
  }
  return p;
}

/** A car's mid-LOD mesh (or its full-mesh fallback) if it has already loaded (undefined while
 * loading or never requested). */
export function carMidMeshNow(carId: string): CarMeshJson | null | undefined {
  return midLoaded.get(carId);
}

/** Start loading every listed car mesh (full and mid LOD); resolves when all have arrived (or
 * failed). */
export function preloadCarMeshes(carIds: string[]): Promise<void> {
  return Promise.all(carIds.flatMap((id) => [loadCarMesh(id), loadCarMidMesh(id)])).then(() => undefined);
}

/** Panel states of an entity, PANEL_STRIDE floats per panel (empty if the build or scenario has none). */
export function panelStates(entity: number): Float32Array {
  try {
    return sim.panelStates(entity);
  } catch {
    return new Float32Array(0);
  }
}

/** Per-part arrays derived from the car mesh file; identical for every car of a model, so they
 * are built once per part (browser perf, round 12b: promotions rebuilt them for each car). */
interface PartData {
  rest: Float32Array;
  /** Atlas / mesh UVs (0..1), 2 per vertex (zeros when the file has none). */
  uv: Float32Array;
  weights: Float32Array;
  foldW: Float32Array;
  nodes: Uint16Array;
  index: Uint16Array | Uint32Array;
  /** Wheel parts are never re-skinned: one geometry for every car of the model. */
  wheelGeom: THREE.BufferGeometry | null;
  /** The crumple binding packed for `chordFoldsInto` (null: the part does not fold). */
  foldPack: FoldPack | null;
}
const partData = new WeakMap<MeshPartJson, PartData>();
const partCentres = new WeakMap<MeshPartJson, THREE.Vector3>();
/** Mean rest position of a part's vertices, metres (chassis space; hub space for wheel parts). */
function centreOf(def: MeshPartJson): THREE.Vector3 {
  let c = partCentres.get(def);
  if (c) return c;
  const rest = dataOf(def).rest;
  const n = rest.length / 3;
  c = new THREE.Vector3();
  for (let i = 0; i < n; i++) c.set(c.x + rest[i * 3], c.y + rest[i * 3 + 1], c.z + rest[i * 3 + 2]);
  if (n) c.divideScalar(n);
  partCentres.set(def, c);
  return c;
}
function dataOf(def: MeshPartJson): PartData {
  let d = partData.get(def);
  if (d) return d;
  const n = def.positions_mm.length / 3;
  const rest = new Float32Array(n * 3);
  for (let i = 0; i < n * 3; i++) rest[i] = def.positions_mm[i] * 1e-3;
  const weights = new Float32Array(def.skin_weights.length);
  for (let i = 0; i < weights.length; i++) weights[i] = def.skin_weights[i] / 255;
  const fw = def.fold && def.fold.chords.length > 0 ? def.fold.weights : [];
  const foldW = new Float32Array(fw.length);
  for (let i = 0; i < fw.length; i++) foldW[i] = fw[i] / 255;
  const index = n > 65535 ? new Uint32Array(def.indices) : new Uint16Array(def.indices);
  const uv = new Float32Array(n * 2);
  for (let i = 0; i < Math.min(def.uvs.length, uv.length); i++) uv[i] = def.uvs[i] / 65535;
  let wheelGeom: THREE.BufferGeometry | null = null;
  if (def.wheel != null) {
    wheelGeom = new THREE.BufferGeometry();
    wheelGeom.setAttribute("position", new THREE.BufferAttribute(rest, 3));
    wheelGeom.setIndex(new THREE.BufferAttribute(index, 1));
  }
  const foldPack = def.fold && def.fold.chords.length > 0 ? packFold(def.fold) : null;
  d = { rest, uv, weights, foldW, nodes: new Uint16Array(def.skin_nodes), index, wheelGeom, foldPack };
  partData.set(def, d);
  return d;
}

/** Stand-in geometry of batched parts' own meshes (never drawn; see `PartRT.mesh`). */
const NO_GEOMETRY = new THREE.BufferGeometry();

/** Greybox values of every panel material, recorded when it is made (applyStyle restores them). */
const greyLook = new WeakMap<THREE.Material, { color: THREE.Color; roughness: number; metalness: number; opacity: number }>();
function std(o: THREE.MeshStandardMaterialParameters): THREE.MeshStandardMaterial {
  const m = new THREE.MeshStandardMaterial({ flatShading: true, side: THREE.DoubleSide, ...o });
  greyLook.set(m, { color: m.color.clone(), roughness: m.roughness, metalness: m.metalness, opacity: m.opacity });
  return m;
}

/**
 * Image-based lighting for car materials (SceneView sets it once: a PMREM of RoomEnvironment),
 * so metallic paint, chrome and bare metal read as metal instead of black (detailed-car-models).
 * Only car materials take it (not `scene.environment`: that would relight the whole city), and
 * only in the greybox style (`applyCarEnv`): low-poly dark is matte and lit by its palette.
 */
let carEnv: THREE.Texture | null = null;
/** envMapIntensity of car materials. */
export const CAR_ENV_INTENSITY = 0.6;
/** Set the car environment map (once, before cars are built; SceneView). */
export function setCarEnvironment(tex: THREE.Texture | null): void {
  carEnv = tex;
}
/** The car environment map (null until SceneView made it). */
export function carEnvironment(): THREE.Texture | null {
  return carEnv;
}
/** Give `m` the car environment map (`on`, greybox) or none (low-poly dark). */
export function applyCarEnv(m: THREE.Material, on: boolean): void {
  if (!(m instanceof THREE.MeshStandardMaterial)) return;
  const env = on ? carEnv : null;
  if (m.envMap === env) return;
  m.envMap = env;
  m.envMapIntensity = CAR_ENV_INTENSITY;
  m.needsUpdate = true;
}

/** Materials that are the same on every car (only paint, livery and the lamps are per car):
 * shared, so a promoted car adds a few materials instead of 20. Mod part materials (steel …
 * stripe) are shared too; a mod that recolours a shared one (tint, interior trim) gets that car
 * its own copy (`PanelBody.setModLook`). Tinted slots (`CarMeshJson.tints`) share one material
 * per slot and colour (`tintedShared`). */
type SharedKind =
  | "glass" | "trim" | "rubber" | "metal" | "interior" | "brokenLamp" | "carbon" | "chrome" | "steel"
  | "caliper" | "caliperSport" | "caliperRace" | "stripe" | "carbonWeave" | "engine" | "grille" | "exhaust" | "rim" | "spring" | "accent";
let sharedMats: Record<SharedKind, THREE.MeshStandardMaterial> | null = null;
/** Every shared material (to tell them from a car's own copies). */
const sharedSet = new Set<THREE.Material>();
function shared(): NonNullable<typeof sharedMats> {
  if (sharedMats) return sharedMats;
  sharedMats = {
    // forceSinglePass: a transparent DoubleSide material is otherwise drawn twice per part
    // (back faces, then front) and Three flips `side`, bumping the material version, so it
    // re-resolved the shader program for every glass part every frame (browser perf pass).
    glass: std({ color: 0x8fb3c4, transparent: true, opacity: 0.38, metalness: 0.1, roughness: 0.1, depthWrite: false, forceSinglePass: true }),
    trim: std({ color: 0x1b1b1d, roughness: 0.9 }),
    rubber: std({ color: 0x141414, roughness: 0.95 }),
    metal: std({ color: 0x9da3a8, metalness: 0.7, roughness: 0.35 }),
    interior: std({ color: 0x2b2724, roughness: 1 }),
    brokenLamp: std({ color: 0x2a2a2c, roughness: 0.6, metalness: 0.4 }),
    carbon: std({ color: 0x1c1d20, metalness: 0.35, roughness: 0.3 }),
    chrome: std({ color: 0xd8dde2, metalness: 0.95, roughness: 0.12 }),
    // Mesh-file slots (format 4); rim / spring / accent / caliper are usually tinted per car.
    caliper: std({ color: 0x3a3c40, metalness: 0.2, roughness: 0.5 }),
    engine: std({ color: 0x3b3d40, metalness: 0.6, roughness: 0.6 }),
    grille: std({ color: 0x0d0e10, roughness: 0.8 }),
    exhaust: std({ color: 0xb9b2a6, metalness: 0.9, roughness: 0.25 }),
    rim: std({ color: 0x9da3a8, metalness: 0.7, roughness: 0.35 }),
    spring: std({ color: 0x3a3c40, metalness: 0.3, roughness: 0.5 }),
    accent: std({ color: 0x8a1020, metalness: 0.25, roughness: 0.55 }),
    // Mod parts only (render/mod_parts.ts).
    steel: std({ color: 0x2a2c2e, metalness: 0.6, roughness: 0.55 }),
    caliperSport: std({ color: 0xc8161d, metalness: 0.2, roughness: 0.45 }),
    caliperRace: std({ color: 0xe0a812, metalness: 0.3, roughness: 0.4 }),
    stripe: std({ color: 0xf2f2f2, roughness: 0.5 }),
    // The texture carries the colour (white base so it is not darkened twice).
    carbonWeave: std({ color: 0xffffff, map: carbonWeaveTexture(), metalness: 0.4, roughness: 0.25 }),
  };
  for (const m of Object.values(sharedMats)) sharedSet.add(m);
  return sharedMats;
}
/**
 * 2x2 twill carbon weave for `carbonWeave`, repeated over the livery atlas UVs of the panels
 * (top band: about 4.8 m of car length across u 0..0.5 and 2 m of width across v 0.5..0.8), so
 * one tile is roughly 14 cm of panel. Real tows are a few mm; this is exaggerated, with strong
 * light/dark contrast, so the weave still reads at game distance and next to a black painted lid.
 */
function carbonWeaveTexture(): THREE.CanvasTexture {
  const c = document.createElement("canvas");
  c.width = c.height = 64;
  const g = c.getContext("2d")!;
  const tow = 16;
  for (let i = 0; i < 4; i++)
    for (let j = 0; j < 4; j++) {
      // Twill: the over/under pattern steps one tow per row.
      const over = (i + j) % 4 < 2;
      const grad = over ? g.createLinearGradient(i * tow, 0, i * tow + tow, 0) : g.createLinearGradient(0, j * tow, 0, j * tow + tow);
      grad.addColorStop(0, over ? "#15181c" : "#08090b");
      grad.addColorStop(0.5, over ? "#737d8a" : "#353b44");
      grad.addColorStop(1, over ? "#15181c" : "#08090b");
      g.fillStyle = grad;
      g.fillRect(i * tow, j * tow, tow, tow);
    }
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(68, 48);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 8;
  return t;
}

/** One shared material per tinted slot and colour (`tints`: every car of a model shares it). */
const tintCache = new Map<string, THREE.MeshStandardMaterial>();
function tintedShared(slot: SharedKind, rgb: [number, number, number]): THREE.MeshStandardMaterial {
  const key = `${slot}:${rgb.join(",")}`;
  let m = tintCache.get(key);
  if (!m) {
    m = shared()[slot].clone();
    rgbColour(rgb, m.color);
    greyLook.set(m, { color: m.color.clone(), roughness: m.roughness, metalness: m.metalness, opacity: m.opacity });
    sharedSet.add(m);
    tintCache.set(key, m);
  }
  return m;
}
/** Slots `tints` may recolour through a shared material. */
const TINTABLE: ReadonlySet<string> = new Set<SharedKind>(["caliper", "rim", "spring", "accent", "engine", "grille", "exhaust", "chrome", "carbon", "metal", "trim", "rubber", "glass", "interior"]);

const tmpStyle = new THREE.Color();
const tmpLb = new THREE.Vector3();
let amberShared: THREE.MeshStandardMaterial | null = null;
/** Amber lenses / advisors of cars that do not flash them. */
function sharedAmber(): THREE.MeshStandardMaterial {
  if (!amberShared) sharedSet.add((amberShared = std({ color: 0xc87a10, emissive: 0x2a1600, roughness: 0.4 })));
  return amberShared;
}
let underglowShared: THREE.MeshStandardMaterial | null = null;
/** Underglow strips while dark (a car with underglow gets its own copy to light). */
function sharedUnderglow(): THREE.MeshStandardMaterial {
  if (!underglowShared) sharedSet.add((underglowShared = std({ color: 0x101012, emissive: 0x000000, roughness: 0.6 })));
  return underglowShared;
}
let glowTex: THREE.CanvasTexture | null = null;
/** Radial white glow (underglow pool), shared. */
function glowTexture(): THREE.CanvasTexture | null {
  if (glowTex) return glowTex;
  const c = document.createElement("canvas");
  c.width = c.height = 64;
  const g = c.getContext("2d");
  if (!g) return null;
  const grad = g.createRadialGradient(32, 32, 4, 32, 32, 32);
  grad.addColorStop(0, "rgba(255,255,255,0.55)");
  grad.addColorStop(0.6, "rgba(255,255,255,0.22)");
  grad.addColorStop(1, "rgba(255,255,255,0)");
  g.fillStyle = grad;
  g.fillRect(0, 0, 64, 64);
  return (glowTex = new THREE.CanvasTexture(c));
}

/** Light-bar lens materials of one side. */
export interface LightbarSide {
  red: THREE.MeshStandardMaterial;
  blue: THREE.MeshStandardMaterial;
  clear: THREE.MeshStandardMaterial;
}
/** Head-lamp materials: one shared, or one per side (left = parts with x < 0) for wig-wag. */
export type LampMaterials = THREE.Material | { left: THREE.Material; right: THREE.Material };

/** Look a mod gives one material (paint finish, window tint, interior trim); unset = unchanged. */
export interface ModLook {
  color?: number;
  roughness?: number;
  metalness?: number;
  opacity?: number;
}
function applyLook(m: THREE.MeshStandardMaterial, l: ModLook): void {
  if (l.color !== undefined) m.color.setHex(l.color);
  if (l.roughness !== undefined) m.roughness = l.roughness;
  if (l.metalness !== undefined) m.metalness = l.metalness;
  if (l.opacity !== undefined) m.opacity = l.opacity;
}

/** Merged index and UVs of one material's batched parts, per car model (every car of the model
 * shares the UV array: it never changes). */
/** Per-model batch templates: merged index and UVs, plus the crease map and its render-layout
 * UVs for smooth batches. */
interface BatchTemplate {
  index: Uint16Array | Uint32Array;
  uv: Float32Array;
  crease?: CreaseMap;
  uvR?: Float32Array;
}
const batchIndex = new WeakMap<CarMeshJson, Map<string, BatchTemplate>>();

/** Largest-triangle node triples per region, per car model (from the rest lattice). */
const spanCache = new Map<string, Map<number, [number, number, number]>>();

interface PartRT {
  def: MeshPartJson;
  /** Material drawn (the mesh file's, or a mod's replacement such as a carbon hood). */
  material: PartMaterial;
  /** Key of the drawn material in `PanelBody.mats` and of its batch: `material`, with "@r" for
   * the right-side head lamps and light-bar lenses (own materials per side). */
  key: string;
  /** A mod part (render/mod_parts.ts): batched apart from the mesh file's parts. */
  mod: boolean;
  /** The part's own mesh: drawn for lenses (their material swaps when broken); for batched parts
   * kept only as a handle (material, name) and never drawn. */
  mesh: THREE.Mesh;
  /** Skinned positions (chassis space). For a batched part a view into its batch's buffer. */
  pos: Float32Array;
  /** Merged draw of all parts with this part's material (null: drawn by `mesh`), and this
   * part's first index in it. */
  batch: Batch | null;
  indexStart: number;
  rest: Float32Array;
  nodes: Uint16Array;
  weights: Float32Array;
  /** Index into `info.regions`, -1 for wheel parts. */
  region: number;
  hidden: boolean;
  /** Crumple binding (null: the part does not fold) and its per-vertex weights (0..1). */
  fold: FoldJson | null;
  foldW: Float32Array;
  /**
   * Crumple memory: per chord the largest effective shortening and leading-end pull-back seen
   * (m). Sheet metal does not spring back; cleared once the car is back at rest (repaired).
   */
  foldMem: Float32Array;
  /** `fold` packed into typed arrays (`chordFoldsInto`); null when `fold` is. */
  foldPack: FoldPack | null;
  /** Drawn by its own mesh (lenses, decal carriers), not a batch. */
  own: boolean;
  /** Light lenses: broken (crushed or their bumper hangs), drawn dark without glow. */
  broken: boolean;
  /** Largest vertex displacement from rest at the last update, m (lights: break check; tests). */
  maxDisp: number;
  /** Largest fold rise at the last update, m (tests). */
  maxFold: number;
  /** Largest leading-end pull-back at the last update, m (tests). */
  maxPull: number;
}

/** skinVertices results: max squared displacement, max fold rise, max pull-back. */
const skinOut = new Float64Array(3);

/** Floats per chord in a packed chord-fold array (`PanelBody.chordFolds`): at, height, extra,
 * pop, u xyz (tools/assets `ChordFold`). */
const CHORD_STRIDE = 7;
/**
 * Scalar inputs of `skinVertices`, packed so the hot loop only reads typed arrays (allocation
 * pass 2026-10-20: reading `f.rt.elements` / chord objects through null-or-object parameters
 * and Smi-valued fold fields deoptimised it again and again, back into a tier where every float
 * operation allocates). Layout: SP_* offsets below.
 */
const SP_FRAME = 0; // 1 = free panel: dents taken in its own frame
const SP_CHORDS = 1; // chord count (0 = the part does not fold)
const SP_ACROSS = 2; // fold axis (0 = x, 2 = z)
const SP_DIR = 3; // fold direction xyz
const SP_REAR = 6; // fixed-edge lift share (free panels)
const SP_RT = 7; // R^T, column-major 3x3
const SP_R = 16; // R, column-major 3x3
const SP_T = 25; // t xyz
const skinParams = new Float64Array(28);

/**
 * Re-skin one part's vertices into `pos` (chassis space): weighted node dents (in the panel's own
 * frame when it is free), plus the crumple fold. A small standalone function so V8 optimises
 * it quickly: inside the big `update` it stayed in an unoptimised tier, where every float
 * operation allocated (~0.35 MB a frame with dented cars, browser-perf.md round 12b). Every
 * input is a typed array (`sp`: SP_* layout; `chords`: CHORD_STRIDE per chord), so the optimised
 * code stays valid whatever the panel states are.
 */
function skinVertices(
  rest: Float32Array,
  pos: Float32Array,
  ids: Uint16Array,
  weights: Float32Array,
  nodes: Float32Array,
  rn: Float32Array,
  sp: Float64Array,
  chords: Float64Array,
  foldW: Float32Array,
  out: Float64Array,
): void {
  const nv = rest.length / 3;
  const framed = sp[SP_FRAME] !== 0;
  const nc = sp[SP_CHORDS] | 0;
  const across = sp[SP_ACROSS] | 0;
  const d0 = sp[SP_DIR];
  const d1 = sp[SP_DIR + 1];
  const d2_ = sp[SP_DIR + 2];
  const rearLift = sp[SP_REAR];
  // Rotations as plain numbers (column-major Matrix3 elements).
  const rt0 = sp[SP_RT];
  const rt1 = sp[SP_RT + 1];
  const rt2 = sp[SP_RT + 2];
  const rt3 = sp[SP_RT + 3];
  const rt4 = sp[SP_RT + 4];
  const rt5 = sp[SP_RT + 5];
  const rt6 = sp[SP_RT + 6];
  const rt7 = sp[SP_RT + 7];
  const rt8 = sp[SP_RT + 8];
  const r0 = sp[SP_R];
  const r1 = sp[SP_R + 1];
  const r2 = sp[SP_R + 2];
  const r3 = sp[SP_R + 3];
  const r4 = sp[SP_R + 4];
  const r5 = sp[SP_R + 5];
  const r6 = sp[SP_R + 6];
  const r7 = sp[SP_R + 7];
  const r8 = sp[SP_R + 8];
  const tx = sp[SP_T];
  const ty = sp[SP_T + 1];
  const tz = sp[SP_T + 2];
  let maxDisp = 0;
  let maxFold = 0;
  let maxPull = 0;
  for (let v = 0; v < nv; v++) {
    let dx = 0;
    let dy = 0;
    let dz = 0;
    for (let k = 0; k < 4; k++) {
      const w = weights[v * 4 + k];
      if (w === 0) continue;
      const i = ids[v * 4 + k] * 3;
      if (framed) {
        // Node in the panel's own frame, minus its rest position = dent.
        const x = nodes[i] - tx;
        const y = nodes[i + 1] - ty;
        const z = nodes[i + 2] - tz;
        dx += w * (rt0 * x + rt3 * y + rt6 * z - rn[i]);
        dy += w * (rt1 * x + rt4 * y + rt7 * z - rn[i + 1]);
        dz += w * (rt2 * x + rt5 * y + rt8 * z - rn[i + 2]);
      } else {
        dx += w * (nodes[i] - rn[i]);
        dy += w * (nodes[i + 1] - rn[i + 1]);
        dz += w * (nodes[i + 2] - rn[i + 2]);
      }
    }
    if (nc > 0) {
      // Chord fold values at this vertex's across coordinate, linear between chords (sorted
      // by `at`; was `foldAt`).
      const xa = rest[v * 3 + across];
      let c = 0; // chord whose values apply (exact), or -1: interpolate between ci - 1 and ci
      let ci = 0;
      let t = 0;
      if (xa <= chords[0]) c = 0;
      else {
        c = (nc - 1) * CHORD_STRIDE;
        for (let i = 1; i < nc; i++) {
          const bAt = chords[i * CHORD_STRIDE];
          if (xa <= bAt) {
            const aAt = chords[(i - 1) * CHORD_STRIDE];
            t = (xa - aAt) / Math.max(bAt - aAt, 1e-4);
            ci = i * CHORD_STRIDE;
            c = -1;
            break;
          }
        }
      }
      let height = 0;
      let extra = 0;
      let pop = 0;
      let ub = 0; // chord the direction `u` comes from
      if (c >= 0) {
        height = chords[c + 1];
        extra = chords[c + 2];
        pop = chords[c + 3];
        ub = c;
      } else {
        const ca = ci - CHORD_STRIDE;
        height = chords[ca + 1] + (chords[ci + 1] - chords[ca + 1]) * t;
        extra = chords[ca + 2] + (chords[ci + 2] - chords[ca + 2]) * t;
        pop = chords[ca + 3] + (chords[ci + 3] - chords[ca + 3]) * t;
        ub = ca;
      }
      // Buckle along the fold direction (crease, plus the fixed edge once free, plus the
      // leading-edge pop) and pull the leading end back with the crushed front.
      const lead = foldW[v * 3 + 2];
      const rise = height * (foldW[v * 3] + rearLift * foldW[v * 3 + 1]) + pop * lead * lead;
      const pull = extra * lead;
      dx += d0 * rise - chords[ub + 4] * pull;
      dy += d1 * rise - chords[ub + 5] * pull;
      dz += d2_ * rise - chords[ub + 6] * pull;
      if (rise > maxFold) maxFold = rise;
      if (pull > maxPull) maxPull = pull;
    }
    const x = rest[v * 3] + dx;
    const y = rest[v * 3 + 1] + dy;
    const z = rest[v * 3 + 2] + dz;
    if (framed) {
      pos[v * 3] = r0 * x + r3 * y + r6 * z + tx;
      pos[v * 3 + 1] = r1 * x + r4 * y + r7 * z + ty;
      pos[v * 3 + 2] = r2 * x + r5 * y + r8 * z + tz;
    } else {
      pos[v * 3] = x;
      pos[v * 3 + 1] = y;
      pos[v * 3 + 2] = z;
    }
    const ex = pos[v * 3] - rest[v * 3];
    const ey = pos[v * 3 + 1] - rest[v * 3 + 1];
    const ez = pos[v * 3 + 2] - rest[v * 3 + 2];
    const d2 = ex * ex + ey * ey + ez * ez;
    if (d2 > maxDisp) maxDisp = d2;
  }
  out[0] = maxDisp;
  out[1] = maxFold;
  out[2] = maxPull;
}

/**
 * Run `skinVertices` on a synthetic part through every branch (free / attached frame, no fold,
 * fold before / between / after its chords, zero and non-zero weights) with fractional values,
 * once, before the first real car. Its type feedback is then complete: V8 optimises it once and
 * keeps that code. Fed only by real cars, it first saw integral values (no dent yet: zero
 * folds, unit weights) and missing branches, and deoptimised on the first crash into a tier
 * where every float operation allocates (~170 KB a frame, allocation pass 2026-10-20). Writes
 * only its own scratch arrays.
 */
let skinWarmed = false;
function warmSkinVertices(): void {
  if (skinWarmed) return;
  skinWarmed = true;
  const nv = 48;
  const nn = 12;
  const rest = new Float32Array(nv * 3);
  const pos = new Float32Array(nv * 3);
  const ids = new Uint16Array(nv * 4);
  const weights = new Float32Array(nv * 4);
  const foldW = new Float32Array(nv * 3);
  const nodes = new Float32Array(nn * 3);
  const rn = new Float32Array(nn * 3);
  for (let i = 0; i < nv * 3; i++) rest[i] = ((i * 37) % 101) / 50.5 - 1.03;
  for (let i = 0; i < nv * 4; i++) {
    ids[i] = (i * 5) % nn;
    weights[i] = i % 4 === 3 ? 0 : 0.21 + (i % 3) * 0.13;
  }
  for (let i = 0; i < nv * 3; i++) foldW[i] = ((i * 13) % 17) / 17.3;
  for (let i = 0; i < nn * 3; i++) {
    rn[i] = ((i * 7) % 23) / 11.7 - 0.97;
    nodes[i] = rn[i] + 0.0137 * ((i % 5) - 2.1);
  }
  const chords = new Float64Array(3 * CHORD_STRIDE);
  for (let c = 0; c < 3; c++) {
    const o = c * CHORD_STRIDE;
    chords[o] = -0.51 + c * 0.49;
    chords[o + 1] = 0.031 * (c + 1.3);
    chords[o + 2] = 0.017 * (c + 0.7);
    chords[o + 3] = 0.011 * (c + 0.4);
    chords[o + 4] = 0.11;
    chords[o + 5] = 0.97;
    chords[o + 6] = 0.21;
  }
  const sp = new Float64Array(skinParams.length);
  const out = new Float64Array(3);
  const ang = 0.13;
  const cs = Math.cos(ang);
  const sn = Math.sin(ang);
  // Rotation about z (column-major) and its transpose.
  const rot = [cs, sn, 0, -sn, cs, 0, 0, 0, 1];
  for (let k = 0; k < 9; k++) {
    sp[SP_R + k] = rot[k] + 1e-3 * k;
    sp[SP_RT + (k % 3) * 3 + Math.floor(k / 3)] = rot[k] + 1e-3 * k;
  }
  sp[SP_T] = 0.031;
  sp[SP_T + 1] = -0.047;
  sp[SP_T + 2] = 0.019;
  sp[SP_ACROSS] = 0;
  sp[SP_DIR] = 0.05;
  sp[SP_DIR + 1] = 0.08;
  sp[SP_DIR + 2] = 0.99;
  for (let n = 0; n < 32; n++) {
    sp[SP_FRAME] = n % 2;
    sp[SP_CHORDS] = n % 4 < 2 ? 3 : 0;
    sp[SP_REAR] = n % 3 === 0 ? FOLD_REAR_LIFT : 0.5 * FOLD_REAR_LIFT;
    skinVertices(rest, pos, ids, weights, nodes, rn, sp, chords, foldW, out);
  }
  // chordFoldsInto: a three-chord fold whose leads sit on panels that are attached, hanging
  // (rotated back about the pivot), detached (skipped) or absent; at rest and dented.
  const fp = packFold({
    chords: [
      [0, 3],
      [1, 4],
      [2, 5],
    ],
    leads: [
      [6, 7, 8],
      [9, 10, 11],
      [8, 9, 10],
    ],
    across: 0,
    dir: [0.05, 0.08, 0.99],
    gain: 1.37,
    max_m: 0.123,
    pop_m: 0.031,
    weights: [],
  });
  const foldMem = new Float32Array(6);
  const regions = new Uint8Array(nn);
  for (let i = 0; i < nn; i++) regions[i] = i < 6 ? 1 : 2 + (i % 4);
  const regionState = new Int8Array(256);
  const states = new Float32Array(4 * PANEL_STRIDE);
  for (let k = 0; k < 4; k++) {
    const o = k * PANEL_STRIDE;
    states[o] = 2 + k;
    states[o + 1] = k;
    states[o + 2] = 0.173 + 0.01 * k;
    states[o + 3] = 0.5;
    states[o + 4] = 0.31;
    states[o + 5] = -0.42;
    states[o + 6] = 0.53;
    states[o + 7] = 0.11;
    states[o + 8] = 0.07;
    states[o + 9] = 0.99;
  }
  const atRest = new Float32Array(rn);
  // Enough calls that V8 optimises it here (it then runs only a few times a frame).
  for (let n = 0; n < 3000; n++) {
    regionState.fill(-1);
    // Rotate which region is attached / unlatched / hanging / detached; one round all absent.
    if (n % 9 !== 0) for (let k = 0; k < 4; k++) regionState[2 + k] = (k + n) % 4;
    regionState[1] = n % 3 === 0 ? -1 : (n % 2) as number;
    sp[SP_FRAME] = n % 2;
    chordFoldsInto(fp, foldMem, rn, n % 5 === 0 ? atRest : nodes, sp, n % 3 === 1, regionState, regions, states, chords);
  }
}

/**
 * One draw for every body part of a car that shares a material (browser perf, round 12b: a car
 * was ~37 draw calls, one per part). Parts skin straight into `position` through their `pos`
 * views; a hidden part (shattered, detached) has its index range collapsed to one vertex.
 */
interface Batch {
  mesh: THREE.Mesh;
  position: THREE.BufferAttribute;
  index: THREE.BufferAttribute;
  /** Re-skinned since the last upload. */
  dirty: boolean;
  /**
   * Smooth-shaded batches (paint / livery, see `SMOOTH_BATCHES`): parts skin into `src`; the
   * drawn `position` / `normal` use the crease map's render layout and are refreshed from `src`
   * when the batch was re-skinned (`render/crease.ts`).
   */
  smooth?: { crease: CreaseMap; src: Float32Array; normal: THREE.BufferAttribute };
}

/**
 * Materials whose batches are drawn smooth-shaded with crease-angle split normals (car-shapes
 * phase 3b): the painted body and its painted mod parts (`mod:paint` / `mod:livery` batches). Their materials are made without `flatShading`; the low-poly art style forces flat
 * shading back on (`render/style.ts`), so that style stays faceted.
 */
const SMOOTH_BATCHES = new Set(["paint", "livery"]);
/** `?flatcars=1`: the flat-shaded body of before phase 3b (A/B shots and perf runs). */
const FLAT_CARS = typeof location !== "undefined" && new URLSearchParams(location.search).has("flatcars");

/** Element-wise equality of two float arrays. */
function sameFloats(a: Float32Array, b: Float32Array): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
  return true;
}

/** Rigid frame of a free panel: x' = R x + t. */
interface Frame {
  r: THREE.Matrix3;
  rt: THREE.Matrix3;
  t: THREE.Vector3;
}

interface Debris {
  /** Sim entity of the car it came off. */
  entity: number;
  obj: THREE.Group;
  vel: THREE.Vector3;
  spin: THREE.Vector3;
  age: number;
}

const bodies = new Map<number, PanelBody>();
const debris: Debris[] = [];
const MAX_DEBRIS = 48;
const DEBRIS_LIFE_S = 40;

/** Feed drained sim events (GlassShattered hides the glass part). Call once per frame. */
export function panelEvents(events: Record<string, Record<string, unknown>>[]): void {
  for (const e of events) {
    const g = e.GlassShattered;
    if (g) bodies.get(Number(g.vehicle))?.shatter(String(g.region));
  }
}

/** Advance visual debris (call once per frame with the frame dt). */
export function stepDebris(dt: number): void {
  for (let i = debris.length - 1; i >= 0; i--) {
    const d = debris[i];
    d.age += dt;
    d.vel.z -= 9.81 * dt;
    d.obj.position.addScaledVector(d.vel, dt);
    const e = new THREE.Euler(d.spin.x * dt, d.spin.y * dt, d.spin.z * dt);
    d.obj.quaternion.multiply(new THREE.Quaternion().setFromEuler(e));
    if (d.obj.position.z < 0.08) {
      d.obj.position.z = 0.08;
      if (d.vel.z < 0) d.vel.z = -0.25 * d.vel.z;
      d.vel.x *= 0.7;
      d.vel.y *= 0.7;
      d.spin.multiplyScalar(0.6);
    }
    if (d.age > DEBRIS_LIFE_S) {
      d.obj.removeFromParent();
      debris.splice(i, 1);
    }
  }
}

/** Remove all visual debris (scene reset). */
export function clearDebris(): void {
  for (const d of debris) d.obj.removeFromParent();
  debris.length = 0;
}

/** Number of visual debris pieces (tests / HUD). */
export function debrisCount(): number {
  return debris.length;
}

/**
 * Geometry of one detached part as debris: its skinned positions `pos` at the moment it came
 * off, with crease-split normals (built from the rest pose `rest`, like the car's smooth
 * batches) and its UVs. The normals matter: the paint and livery materials are smooth shaded,
 * and a mesh without a normal attribute reads a zero normal, which lights to NaN (black in
 * greybox, a white bloom halo in low-poly dark: "parts falling off are glowing").
 */
export function debrisGeometry(rest: Float32Array, pos: Float32Array, index: ArrayLike<number>, uv: ArrayLike<number>): THREE.BufferGeometry {
  const c = buildCrease(rest, index);
  const nr = c.map.length;
  const position = new Float32Array(nr * 3);
  const normal = new Float32Array(nr * 3);
  const uvR = new Float32Array(nr * 2);
  updateCrease(c, pos, c.index, position, normal);
  for (let r = 0; r < nr; r++) {
    uvR[r * 2] = uv[c.map[r] * 2] ?? 0;
    uvR[r * 2 + 1] = uv[c.map[r] * 2 + 1] ?? 0;
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute("position", new THREE.BufferAttribute(position, 3));
  geom.setAttribute("normal", new THREE.BufferAttribute(normal, 3));
  geom.setAttribute("uv", new THREE.BufferAttribute(uvR, 2));
  geom.setIndex(new THREE.BufferAttribute(c.index, 1));
  return geom;
}

/**
 * Material a detached part is drawn with as debris. Body parts keep the material they were
 * drawn with on the car (paint, livery, trim …: same colour and lighting). Lamp lenses and the
 * other glow slots (light bar, amber beacons, indicators, underglow) belong to the car's live
 * light state, so a lens lying in the road would keep glowing with the car's headlights: they
 * take the dark broken-lamp material instead.
 */
export function debrisMaterial(kind: string, key: string, drawn: THREE.Material, brokenLamp: THREE.Material): THREE.Material {
  return kind === "light" || UNSTYLED(key) ? brokenLamp : drawn;
}

/** One mesh of a visual debris piece, as `debrisAudit` reports it (e2e/debris_glow.mjs). */
export interface DebrisMeshInfo {
  /** Sim entity of the car it came off. */
  vehicle: number;
  /** Mesh part name (`bumper_front`, `headlight_l` …). */
  name: string;
  /** Mesh part kind (`panel`, `light`, `glass` …). */
  kind: string;
  /** Position of the debris piece in the world group (sim coordinates, m). */
  at: [number, number, number];
  /** The mesh has a `normal` attribute with no zero-length normal. */
  normals: boolean;
  /** Material is flat shaded (normals come from screen-space derivatives instead). */
  flat: boolean;
  /** Emissive colour × intensity, max channel (0 = does not glow). */
  emissive: number;
  /** Material is the broken-lamp material (dark lens). */
  brokenLamp: boolean;
  /** Material is lit (not MeshBasicMaterial and the like). */
  lit: boolean;
}

/** Every mesh of the live debris pieces with its shading inputs (tests: debris must shade
 * like the panel it came from and never glow). */
export function debrisAudit(): DebrisMeshInfo[] {
  const out: DebrisMeshInfo[] = [];
  for (const d of debris) {
    const p = d.obj.position;
    for (const c of d.obj.children) {
      if (!(c instanceof THREE.Mesh)) continue;
      const mat = c.material as THREE.Material;
      const std = mat instanceof THREE.MeshStandardMaterial ? mat : null;
      const n = c.geometry.getAttribute("normal") as THREE.BufferAttribute | undefined;
      let normals = !!n;
      if (n) {
        for (let i = 0; i < n.count && normals; i++) {
          const x = n.getX(i), y = n.getY(i), z = n.getZ(i);
          normals = x * x + y * y + z * z > 1e-6;
        }
      }
      out.push({
        vehicle: d.entity,
        name: c.name,
        kind: String(c.userData.kind ?? ""),
        at: [p.x, p.y, p.z],
        normals,
        flat: std?.flatShading ?? false,
        emissive: std ? Math.max(std.emissive.r, std.emissive.g, std.emissive.b) * std.emissiveIntensity : 0,
        brokenLamp: mat === shared().brokenLamp,
        lit: !!std,
      });
    }
  }
  return out;
}

/** Mesh parts that are indicator lenses (`indicator_front_l`, `indicator_rear_r`,
 * `indicator_side_l` …; data/panels mesh contract: kind `light`, `_l` = x < 0). */
export function isIndicatorPart(name: string): boolean {
  return name.startsWith("indicator_");
}

/** Side of an indicator part: by its `_l` / `_r` suffix, else by the sign of its centroid x
 * (`positions`: xyz per vertex, chassis space, any unit). */
export function indicatorRight(name: string, positions: ArrayLike<number>): boolean {
  if (name.endsWith("_r")) return true;
  if (name.endsWith("_l")) return false;
  let cx = 0;
  for (let i = 0; i < positions.length; i += 3) cx += positions[i];
  return cx > 0;
}

/** Options of a PanelBody. */
export interface PanelBodyOptions {
  /** Keep the given paint colour even if the mesh file tints `paint` (traffic, police, parked
   * cars: the instanced fleet draws them in that colour, so a promotion must not recolour). */
  keepPaint?: boolean;
  /**
   * Blink materials of the mesh's indicator lenses (parts named `indicator_*`, render/fleet.ts
   * isIndicatorPart), per side (left = `_l`, x < 0): `amber`, and `red` for red-on-red rear
   * lamps (parts in `taillight`). Unset: indicator parts draw their own material (amber lens,
   * tail lamp) like any lamp.
   */
  indicators?: { amber: { left: THREE.Material; right: THREE.Material }; red: { left: THREE.Material; right: THREE.Material } };
}

/** Material keys PanelBody.applyStyle leaves alone (lamps belong to their owner; flashing lenses,
 * amber and underglow are driven by emissive). */
const UNSTYLED = (k: string) =>
  k === "headlight" ||
  k === "headlight@r" ||
  k === "taillight" ||
  k.startsWith("lightbar_") ||
  k === "emissive_amber" ||
  k === "underglow" ||
  k.startsWith(IND_KEY);
/** Material keys of indicator lenses (`PanelBodyOptions.indicators`): IND_KEY + "amber" / "red",
 * with "@r" on the right. */
const IND_KEY = "indicator:";
/** Mesh-file slots that get one material per side (left x < 0, right "@r"). */
const SIDED = (m: string) => m === "headlight" || m.startsWith("lightbar_");
const BLACK = new THREE.Color(0x000000);
const WHITE = new THREE.Color(0xffffff);

/** All per-panel meshes of one vehicle. Empty (ready = false) until the mesh file loads. */
export class PanelBody {
  /** Re-skins done since the page loaded, all cars (perf checks: should not grow while nothing
   * dents). */
  static reskins = 0;
  /** Smooth batches whose normals were recomputed (perf counter, see `render/crease.ts`). */
  static normalUpdates = 0;
  readonly root = new THREE.Group();
  ready = false;
  /** Parts per wheel index, hub space (VehicleView parents them under its spinning wheel groups). */
  readonly wheelParts: THREE.Mesh[][] = [[], [], [], []];
  /** Non-spinning parts per wheel index, hub space: the mesh file's calipers / uprights and mod
   * brake calipers (VehicleView parents them under the steered hub, not the spinning wheel). */
  readonly hubParts: THREE.Mesh[][] = [[], [], [], []];
  /** Visual camber per wheel, radians about +Y (sign already per side: + tilts the top toward +X). */
  readonly camberRad: number[] = [0, 0, 0, 0];
  /** The loaded mesh file (null until ready). */
  mesh: CarMeshJson | null = null;
  /** Livery atlas frame of this car (DEFAULT_ATLAS until the mesh loads / for format-1 files). */
  atlas: LiveryAtlas = DEFAULT_ATLAS;
  /** Livery hint from the mesh file, if any. */
  liveryHint: LiveryHint | null = null;
  /** Light-bar lens centres per side, chassis space (null if the car has none). */
  readonly lightbarAnchors: { left: THREE.Vector3 | null; right: THREE.Vector3 | null } = { left: null, right: null };
  /** Latest panel states (PANEL_STRIDE floats per panel). */
  states: Float32Array = new Float32Array(0);
  private parts: PartRT[] = [];
  /** Merged per-material draws of the body parts (`Batch`), by batch key (`batchKey`). */
  private batches: Batch[] = [];
  private readonly batchByKey = new Map<string, Batch>();
  /** Parts or part materials changed since the batches were built (`rebatch`). */
  private batchesStale = false;
  /** A part draws another material than its mesh file says: the per-model index cache no
   * longer matches this car's batches. */
  private customBatches = false;
  /** Looks mods gave materials (`setModLook`), re-applied over every art style. */
  private readonly modLooks = new Map<PartMaterial, ModLook>();
  /** Region names of the car (`vehicle_info.regions`; index = region code). */
  readonly regions: string[];
  /** Lattice rest nodes, chassis space (xyz per node). */
  restNodes: Float32Array = new Float32Array(0);
  /** Region index of every lattice node. */
  nodeRegions: Uint8Array = new Uint8Array(0);
  /** Dark, unlit lens of a broken light. */
  private readonly brokenLamp: THREE.Material;
  /** Region index → three node ids spanning the panel (frame fit), for panel regions. */
  private readonly tri = new Map<number, [number, number, number]>();
  private readonly frames = new Map<number, Frame>();
  /** One reusable `Frame` per free panel region (`frames` holds this re-skin's). */
  private readonly framePool = new Map<number, Frame>();
  private readonly spawned = new Set<number>();
  /** Drawn material per key (`PartRT.key`): shared ones, this car's paint / livery / lamps,
   * and copies made for this car (`ownCopy`). */
  private readonly mats: Record<string, THREE.Material>;
  /** Light-bar lens materials per side, made on first use (`lightbarMaterials`). */
  private lens: { left: LightbarSide; right: LightbarSide } | null = null;
  /** Underglow colour from the mesh tints (null: the car has none). */
  private underglowColour: THREE.Color | null = null;
  /** Soft additive glow on the road under the car (cars with underglow only). */
  private underglowPool: THREE.Mesh | null = null;
  /** Livery texture on the `livery` parts (null: plain body colour). */
  private livery: THREE.Texture | null = null;
  /** Paint colour the livery scheme asks for (mirrors, plain paint parts), kept over art styles. */
  private liveryBase: THREE.Color | null = null;
  private readonly keepPaint: boolean;
  /** Indicator parts draw the owner's blink materials (`PanelBodyOptions.indicators`). */
  private indicatorLenses = false;
  private onReady: (() => void) | null = null;
  /** Nodes array of the last re-skin (VehicleView swaps in a new array only when they move). */
  private skinnedNodes: Float32Array | null = null;
  private readonly stateOf = new Map<number, number>();
  /** Panel state code per region index, -1 = no panel (`stateOf` as a typed array, for
   * `chordFoldsInto`). */
  private readonly regionState = new Int8Array(256);
  /** Packed chord folds of the part being re-skinned (`chordFoldsInto`, CHORD_STRIDE per chord). */
  private chordBuf = new Float64Array(CHORD_STRIDE * 4);
  private disposed = false;
  /** Mesh part of each wheel-space mesh (workshop picking). */
  private readonly wheelDefs = new Map<THREE.Mesh, MeshPartJson>();
  /** Workshop highlight overlays and their material. */
  private glow: THREE.Mesh[] = [];
  private glowMat: THREE.MeshBasicMaterial | null = null;

  constructor(
    readonly entity: number,
    readonly carId: string,
    paint: THREE.Color | number,
    headlight: LampMaterials,
    taillight: THREE.Material,
    opts: PanelBodyOptions = {},
  ) {
    this.regions = sim.info(entity).regions;
    this.keepPaint = opts.keepPaint ?? false;
    const sm = shared();
    const headL = headlight instanceof THREE.Material ? headlight : headlight.left;
    const headR = headlight instanceof THREE.Material ? headlight : headlight.right;
    this.mats = {
      ...sm,
      // Smooth shaded (crease-split normals on their batches, SMOOTH_BATCHES); the low-poly style
      // flattens them again.
      paint: std({ color: paint, metalness: 0.25, roughness: 0.55, flatShading: FLAT_CARS }),
      // Body panels of format-4 meshes: the paint colour, or the livery texture (setLivery).
      livery: std({ color: paint, metalness: 0.25, roughness: 0.55, flatShading: FLAT_CARS }),
      headlight: headL,
      "headlight@r": headR,
      taillight,
      // Shared until this car flashes them (`amberMaterials`) / lights them (`setUnderglow`).
      emissive_amber: sharedAmber(),
      underglow: sharedUnderglow(),
    };
    for (const m of [this.mats.paint, this.mats.livery]) applyCarEnv(m, true);
    const ind = opts.indicators;
    if (ind) {
      this.indicatorLenses = true;
      this.mats[`${IND_KEY}amber`] = ind.amber.left;
      this.mats[`${IND_KEY}amber@r`] = ind.amber.right;
      this.mats[`${IND_KEY}red`] = ind.red.left;
      this.mats[`${IND_KEY}red@r`] = ind.red.right;
    }
    this.brokenLamp = sm.brokenLamp;
    warmSkinVertices();
    bodies.set(entity, this);
    // Preloaded (session start, render/fleet.ts): build now, so the car never shows a frame
    // without its mesh. Otherwise build when the file arrives — unless the car is gone by then
    // (a promoted traffic car demoted again between two frames; the view is disposed next frame).
    const now = carMeshNow(carId);
    if (now) this.build(now);
    else if (now === undefined)
      void loadCarMesh(carId).then((m) => {
        if (!m || this.disposed || bodies.get(entity) !== this) return;
        try {
          this.build(m);
        } catch {
          // wp_wasm: unknown entity — the sim already removed the vehicle.
        }
      });
  }

  /** Called once the mesh has loaded (immediately if it already has). */
  whenReady(fn: () => void): void {
    if (this.ready) return fn();
    const prev = this.onReady;
    this.onReady = prev ? () => (prev(), fn()) : fn;
  }

  /**
   * Art style (render/style.ts): low-poly dark takes paint, glass, trim, tire, rim and interior
   * colours from the palette and makes every part matte; greybox restores the values above.
   * Head/tail lamps are the VehicleView's shared materials and are styled there.
   * `ownPaint`: `paint` is the car's own colour (VehicleView `setPaint` / the session's entity paint),
   * drawn in greybox too.
   */
  applyStyle(lowpoly: boolean, paint: THREE.Color, ownPaint = false): void {
    const lp: Partial<Record<string, number>> = {
      glass: PALETTE.glass,
      trim: PALETTE.trim,
      rubber: PALETTE.tire,
      metal: PALETTE.rim,
      interior: PALETTE.interior,
    };
    for (const [k, m] of Object.entries(this.mats)) {
      const g = UNSTYLED(k) || k === "livery" ? undefined : greyLook.get(m);
      if (!g || !(m instanceof THREE.MeshStandardMaterial)) continue;
      // Shared materials are styled by every car alike (same values), env included.
      applyCarEnv(m, !lowpoly);
      // The car's own paint (career / lot car, respray, paint-shop preview) in every style;
      // otherwise greybox keeps the mesh's factory colour.
      if (k === "paint") m.color.copy(this.liveryBase ?? (lowpoly || ownPaint ? paint : g.color));
      else m.color.copy(lowpoly && lp[k] !== undefined ? tmpStyle.setHex(lp[k]) : g.color);
      // Bought carbon keeps its gloss in low-poly too, so it never reads as a matte black lid.
      const gloss = k === "carbonWeave";
      m.roughness = lowpoly && !gloss ? (k === "glass" ? 0.35 : 0.85) : g.roughness;
      m.metalness = lowpoly && !gloss ? (k === "paint" ? 0.15 : 0) : g.metalness;
      // Low-poly glass is darker and less see-through (picker: near-opaque blue-black).
      if (k === "glass") m.opacity = lowpoly ? 0.82 : g.opacity;
      // What the player bought shows in every style.
      const look = this.modLooks.get(k as PartMaterial);
      if (look) applyLook(m, look);
    }
    applyCarEnv(this.mats.livery, !lowpoly);
    this.syncLivery(true);
    const b = this.brokenLamp as THREE.MeshStandardMaterial;
    const bg = greyLook.get(b)!;
    b.color.copy(lowpoly ? tmpStyle.setHex(PALETTE.brokenLight) : bg.color);
    this.onStyled?.();
  }

  /** Paint material (body colour). VehicleView sets its opacity; the livery material follows it. */
  get paint(): THREE.MeshStandardMaterial {
    return this.mats.paint as THREE.MeshStandardMaterial;
  }

  /** Livery material (body panels of format-4 meshes: paint colour, or the livery texture). */
  get liveryMaterial(): THREE.MeshStandardMaterial {
    return this.mats.livery as THREE.MeshStandardMaterial;
  }

  /**
   * The livery material follows the paint: opacity always (VehicleView fades the paint for the
   * lattice view), colour / finish when no texture is set (`all`: finish too).
   */
  private syncLivery(all = false): void {
    const pm = this.paint;
    const lm = this.liveryMaterial;
    if (lm.opacity !== pm.opacity || lm.transparent !== pm.transparent) {
      lm.opacity = pm.opacity;
      lm.transparent = pm.transparent;
      lm.depthWrite = pm.depthWrite;
    }
    if (!all) return;
    lm.color.copy(this.livery ? WHITE : pm.color);
    lm.roughness = pm.roughness;
    lm.metalness = pm.metalness;
  }

  /**
   * Show `texture` (a canvas laid out as the livery atlas, see liveryPx) on the livery parts, or
   * go back to the plain body colour with null. `base` is the scheme's paint colour for the plain
   * paint parts (mirrors), kept over art styles. The texture's colours are used as-is (white
   * material colour) while it is set.
   */
  setLivery(texture: THREE.Texture | null, base: THREE.Color | null = null): void {
    this.livery = texture;
    this.liveryBase = texture ? base : null;
    if (this.liveryBase) this.paint.color.copy(this.liveryBase);
    const m = this.liveryMaterial;
    m.map = texture;
    m.needsUpdate = true;
    this.syncLivery(true);
  }

  /** The material of a mesh-file slot on this car (tints applied once the mesh loaded). */
  materialFor(slot: MaterialJson): THREE.Material {
    return this.mat(slot);
  }

  /** Light-bar lens materials per side (left = parts with x < 0); flash them via `emissive`. */
  get lightbarMaterials(): { left: LightbarSide; right: LightbarSide } {
    if (!this.lens) {
      const lens = (color: number) => std({ color, emissive: 0x000000, roughness: 0.3, transparent: true, opacity: 0.9, forceSinglePass: true });
      const side = (): LightbarSide => ({ red: lens(0x661018), blue: lens(0x102266), clear: lens(0xbfc4c8) });
      this.lens = { left: side(), right: side() };
    }
    return this.lens;
  }

  /** Amber emissive material(s) of this car (advisors, beacons, amber lenses): its own copy, so
   * flashing it via `emissive` does not flash every car. */
  get amberMaterials(): THREE.MeshStandardMaterial[] {
    return [this.ownCopy("emissive_amber")];
  }

  /** True when the mesh has underglow strips (after load). */
  get hasUnderglow(): boolean {
    return this.underglowColour !== null;
  }

  /** Light (true) or darken the underglow strips; no-op for cars without underglow. */
  setUnderglow(on: boolean): void {
    if (!this.underglowColour) return;
    const m = this.mats.underglow as THREE.MeshStandardMaterial;
    m.emissive.copy(on ? this.underglowColour : BLACK);
    m.emissiveIntensity = on ? 1.6 : 1;
    if (this.underglowPool) this.underglowPool.visible = on;
  }

  /** Additive radial glow quad on the ground (chassis z ≈ 0) under the car's footprint. */
  private buildUnderglowPool(colour: THREE.Color): void {
    const a = this.atlas;
    const geo = new THREE.PlaneGeometry(2 * a.x_half + 0.9, a.y[1] - a.y[0] + 0.6);
    const mat = new THREE.MeshBasicMaterial({
      color: colour,
      map: glowTexture(),
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    });
    const pool = new THREE.Mesh(geo, mat);
    pool.name = "underglow_pool";
    pool.position.set(0, (a.y[0] + a.y[1]) / 2, 0.02);
    pool.renderOrder = 1;
    pool.visible = false;
    this.root.add(pool);
    this.underglowPool = pool;
  }

  /** Material of a key (`PartRT.key`): light-bar lenses are made on first use. */
  private mat(key: string): THREE.Material {
    const m = this.mats[key];
    if (m) return m;
    if (key.startsWith("lightbar_")) {
      const right = key.endsWith("@r");
      const colour = key.slice("lightbar_".length).replace("@r", "") as keyof LightbarSide;
      const lb = this.lightbarMaterials[right ? "right" : "left"][colour];
      if (lb) return (this.mats[key] = lb);
    }
    return this.mats.paint; // unknown slot (newer file) → paint
  }

  /** This car's own copy of a shared material (swapped into its batches, lenses and wheel parts). */
  private ownCopy(key: string): THREE.MeshStandardMaterial {
    const m = this.mat(key) as THREE.MeshStandardMaterial;
    if (!sharedSet.has(m)) return m;
    const own = m.clone();
    const g = greyLook.get(m);
    if (g) greyLook.set(own, { color: g.color.clone(), roughness: g.roughness, metalness: g.metalness, opacity: g.opacity });
    for (const b of this.batches) if (b.mesh.material === m) b.mesh.material = own;
    for (const p of this.parts) if (p.mesh.material === m) p.mesh.material = own;
    for (const list of [this.wheelParts, this.hubParts]) for (const w of list) for (const wm of w) if (wm.material === m) wm.material = own;
    this.mats[key] = own;
    return own;
  }

  /** Key of a mesh-file part's material: sided slots get "@r" on the right (centroid x > 0);
   * indicator lenses their side's blink material (when the owner gave them). */
  private keyOf(material: PartMaterial, rest: Float32Array, name = ""): string {
    if (this.indicatorLenses && isIndicatorPart(name)) {
      const hue = material === "taillight" ? "red" : "amber";
      return `${IND_KEY}${hue}${indicatorRight(name, rest) ? "@r" : ""}`;
    }
    if (!SIDED(material)) return material;
    let cx = 0;
    const n = rest.length / 3;
    for (let i = 0; i < n; i++) cx += rest[i * 3];
    return cx > 0 ? `${material}@r` : material;
  }

  private build(mesh: CarMeshJson): void {
    this.mesh = mesh;
    this.restNodes = sim.latticeRest(this.entity);
    this.nodeRegions = sim.latticeRegions(this.entity);
    if (mesh.atlas) this.atlas = mesh.atlas;
    this.liveryHint = mesh.livery ?? null;
    for (const [slot, rgb] of Object.entries(mesh.tints ?? {}) as [MaterialJson, [number, number, number]][]) {
      if (!rgb) continue;
      if (slot === "underglow") {
        // Emissive colour, lit by setUnderglow (VehicleView: with the headlights).
        this.underglowColour = rgbColour(rgb);
        this.ownCopy("underglow");
      } else if (slot === "paint") {
        // The model's factory colour (player / AI cars; the fleet's cars keep their livery).
        if (this.keepPaint) continue;
        rgbColour(rgb, this.paint.color);
        greyLook.get(this.paint)?.color.copy(this.paint.color);
        this.syncLivery(true);
      } else if (TINTABLE.has(slot)) {
        this.mats[slot] = tintedShared(slot as SharedKind, rgb);
      }
    }
    (mesh.wheel_camber_deg ?? [0, 0, 0, 0]).forEach((deg, i) => {
      // Wheels 0, 2 are on the left (−X): + camber tilts their top toward +X.
      this.camberRad[i] = (((i % 2 === 0 ? 1 : -1) * deg) * Math.PI) / 180;
    });
    const lbSum = { left: new THREE.Vector3(), right: new THREE.Vector3() };
    const lbCount = { left: 0, right: 0 };
    for (const def of mesh.parts) {
      const d = dataOf(def);
      const region = def.region ? this.regions.indexOf(def.region) : -1;
      const key = this.keyOf(def.material, d.rest, def.wheel == null ? def.name : "");
      if (d.wheelGeom) {
        // Wheel parts follow VehicleView's wheel groups and are never re-skinned: tire / rim /
        // disc spin, caliper / upright only steer.
        const wm = new THREE.Mesh(d.wheelGeom, this.mat(key));
        wm.name = def.name;
        this.wheelDefs.set(wm, def);
        wm.frustumCulled = false;
        (HUB_KINDS.has(def.kind) ? this.hubParts : this.wheelParts)[def.wheel!].push(wm);
        continue;
      }
      if (def.material.startsWith("lightbar_")) {
        const side = key.endsWith("@r") ? "right" : "left";
        const n = d.rest.length / 3;
        for (let i = 0; i < n; i++) lbSum[side].add(tmpLb.fromArray(d.rest, i * 3).divideScalar(n));
        lbCount[side]++;
      }
      const pos = d.rest.slice();
      // Lenses keep their own mesh (broken lenses swap material), decal carriers too (their UVs
      // and material are per unit, render/livery.ts applyUnitDecals); every other body part is
      // drawn by its material's batch (buildBatches) and keeps a never-drawn handle mesh.
      const own = def.kind === "light" || def.kind === "decal_carrier";
      let m: THREE.Mesh;
      if (own) {
        const geom = new THREE.BufferGeometry();
        geom.setAttribute("position", new THREE.BufferAttribute(pos, 3));
        geom.setAttribute("uv", new THREE.BufferAttribute(d.uv.slice(), 2));
        geom.setIndex(new THREE.BufferAttribute(d.index, 1));
        // Lenses use the shared head/tail materials: with a normal attribute they shade even
        // where the material is not flat-shaded.
        if (def.kind === "light") geom.computeVertexNormals();
        m = new THREE.Mesh(geom, this.mat(key));
        m.frustumCulled = false;
        this.root.add(m);
      } else {
        m = new THREE.Mesh(NO_GEOMETRY, this.mat(key));
      }
      m.name = def.name;
      const fold = def.fold && def.fold.chords.length > 0 ? def.fold : null;
      this.parts.push({
        def,
        material: def.material,
        key,
        mod: false,
        mesh: m,
        pos,
        batch: null,
        indexStart: 0,
        rest: d.rest,
        nodes: d.nodes,
        weights: d.weights,
        region,
        hidden: false,
        fold,
        foldW: d.foldW,
        foldMem: new Float32Array((fold?.chords.length ?? 0) * 2),
        foldPack: fold ? d.foldPack : null,
        own,
        broken: false,
        maxDisp: 0,
        maxFold: 0,
        maxPull: 0,
      });
      this.ensureTri(region);
    }
    for (const side of ["left", "right"] as const)
      if (lbCount[side] > 0) this.lightbarAnchors[side] = lbSum[side].divideScalar(lbCount[side]);
    if (this.underglowColour) this.buildUnderglowPool(this.underglowColour);
    this.buildBatches();
    this.ready = true;
    if (liveryFlag() === "grid") this.setLivery(debugLiveryTexture(this.atlas));
    this.update(this.restNodes, 0);
    this.onReady?.();
  }

  /** Frame-fit node triple of a panel region (cached per car model). */
  private ensureTri(region: number): void {
    if (region < 0 || this.tri.has(region)) return;
    let spans = spanCache.get(this.carId);
    if (!spans) spanCache.set(this.carId, (spans = new Map()));
    let t = spans.get(region);
    if (!t) spans.set(region, (t = spanTriangle(this.restNodes, this.nodeRegions, region)));
    this.tri.set(region, t);
  }

  /**
   * Add mod body parts (render/mod_parts.ts; `kind` "mod", `wheel` unset): skinned to their
   * `skin_nodes` like any mesh-file part, so they dent, swing with a hinged panel and leave as
   * debris with their region. Drawn once `rebatch` has run (one batch per mod material).
   */
  addModParts(defs: MeshPartJson[]): void {
    for (const def of defs) {
      const d = dataOf(def);
      const region = def.region ? this.regions.indexOf(def.region) : -1;
      this.parts.push({
        def,
        material: def.material,
        key: def.material,
        mod: true,
        mesh: new THREE.Mesh(NO_GEOMETRY, this.mat(def.material)),
        pos: d.rest.slice(),
        batch: null,
        indexStart: 0,
        rest: d.rest,
        nodes: d.nodes,
        weights: d.weights,
        region,
        hidden: false,
        fold: null,
        foldW: d.foldW,
        foldMem: new Float32Array(0),
        foldPack: null,
        own: false,
        broken: false,
        maxDisp: 0,
        maxFold: 0,
        maxPull: 0,
      });
      this.parts[this.parts.length - 1].mesh.name = def.name;
      this.ensureTri(region);
    }
    this.batchesStale = true;
  }

  /** Add a mod wheel part (`wheel` set; hub space): it spins with the wheel, or with `hub` only
   * steers (brake calipers). Call before VehicleView parents the wheel parts. */
  addWheelPart(def: MeshPartJson, hub = false): THREE.Mesh {
    const m = new THREE.Mesh(dataOf(def).wheelGeom!, this.mat(def.material));
    m.name = def.name;
    m.frustumCulled = false;
    (hub ? this.hubParts : this.wheelParts)[def.wheel!].push(m);
    return m;
  }

  /** Draw the body parts `which` selects with `material` instead (a carbon hood); applies at
   * the next `rebatch`. */
  setPartMaterial(which: (def: MeshPartJson) => boolean, material: PartMaterial): void {
    for (const p of this.parts) {
      if (p.own || !which(p.def)) continue;
      p.material = material;
      p.key = material;
      p.mesh.material = this.mat(material);
      this.customBatches = true;
      this.batchesStale = true;
    }
  }

  /**
   * A mod's look for one material (paint finish, window tint, interior trim), kept over art
   * style changes. A shared material is first copied for this car, so other cars keep theirs.
   */
  setModLook(material: PartMaterial, look: ModLook): void {
    if (!(this.mat(material) instanceof THREE.MeshStandardMaterial)) return;
    const m = this.ownCopy(material);
    this.modLooks.set(material, { ...this.modLooks.get(material), ...look });
    applyLook(m, look);
    // The body panels of format-4 meshes are `livery`: a paint finish shows on them too.
    if (material === "paint") this.syncLivery(true);
  }

  /** Rebuild the batches after `addModParts` / `setPartMaterial` (one-off, at spawn). */
  rebatch(): void {
    if (!this.batchesStale) return;
    this.batchesStale = false;
    for (const b of this.batches) {
      b.mesh.removeFromParent();
      b.mesh.geometry.dispose();
    }
    this.batches.length = 0;
    this.batchByKey.clear();
    for (const p of this.parts) {
      if (!p.batch) continue;
      p.pos = p.pos.slice();
      p.batch = null;
    }
    this.buildBatches();
    for (const p of this.parts) if (p.hidden) this.hidePart(p);
    // Re-skin the new parts on the next update even if the nodes did not move.
    this.skinnedNodes = null;
    if (this.ready) this.update(this.restNodes, 0);
  }

  /** The merged draw of the mesh file's parts made of `material` (null: none). Mod effects that
   * draw over the body (vinyl overlay) share its skinned geometry. */
  batchMesh(material: PartMaterial): THREE.Mesh | null {
    return this.batchByKey.get(material)?.mesh ?? null;
  }

  /** Merge the non-lens body parts into one mesh per material (see `Batch`); mod parts get
   * batches of their own (key "mod:<material>"), so the mesh file's batches stay per model. */
  private buildBatches(): void {
    const mesh = this.mesh!;
    let cached = batchIndex.get(mesh);
    if (!cached) batchIndex.set(mesh, (cached = new Map()));
    const groups = new Map<string, PartRT[]>();
    for (const p of this.parts) {
      if (p.own) continue;
      const key = p.mod ? `mod:${p.key}` : p.key;
      let g = groups.get(key);
      if (!g) groups.set(key, (g = []));
      g.push(p);
    }
    for (const [key, parts] of groups) {
      const material = parts[0].key;
      let nv = 0;
      let ni = 0;
      for (const p of parts) {
        nv += p.rest.length / 3;
        ni += p.def.indices.length;
      }
      const pos = new Float32Array(nv * 3);
      // The merged index is the same for every car of the model: build it once, copy it per car
      // (hidden parts are collapsed in the copy). Mod parts and re-materialed parts are this
      // car's own: their index is built for it alone.
      const own = parts[0].mod || this.customBatches;
      let tmpl = own ? undefined : cached.get(key);
      if (!tmpl) {
        const index = nv > 65535 ? new Uint32Array(ni) : new Uint16Array(ni);
        const uv = new Float32Array(nv * 2);
        let v = 0;
        let i = 0;
        for (const p of parts) {
          const idx = p.def.indices;
          for (let k = 0; k < idx.length; k++) index[i + k] = idx[k] + v;
          uv.set(dataOf(p.def).uv, v * 2);
          v += p.rest.length / 3;
          i += idx.length;
        }
        tmpl = { index, uv };
        if (!own) cached.set(key, tmpl);
      }
      let v0 = 0;
      let i0 = 0;
      for (const p of parts) {
        pos.set(p.pos, v0 * 3);
        p.pos = pos.subarray(v0 * 3, v0 * 3 + p.rest.length);
        p.indexStart = i0;
        v0 += p.rest.length / 3;
        i0 += p.def.indices.length;
      }
      const geom = new THREE.BufferGeometry();
      let smooth: Batch["smooth"];
      let position: THREE.BufferAttribute;
      let indexAttr: THREE.BufferAttribute;
      if (!FLAT_CARS && SMOOTH_BATCHES.has(material)) {
        // Crease map from the rest pose (per model, like the index template; a mod batch
        // ("mod:paint": body kits, wings, lips, flares) is this car's own, built once with it).
        let c = own ? undefined : tmpl.crease;
        if (!c) {
          const rest = new Float32Array(nv * 3);
          let r0 = 0;
          for (const p of parts) {
            rest.set(p.rest, r0);
            r0 += p.rest.length;
          }
          c = buildCrease(rest, tmpl.index);
          tmpl.uvR = new Float32Array(c.map.length * 2);
          for (let r = 0; r < c.map.length; r++) {
            tmpl.uvR[r * 2] = tmpl.uv[c.map[r] * 2];
            tmpl.uvR[r * 2 + 1] = tmpl.uv[c.map[r] * 2 + 1];
          }
          if (!own) tmpl.crease = c;
        }
        const nr = c.map.length;
        position = new THREE.BufferAttribute(new Float32Array(nr * 3), 3);
        const normal = new THREE.BufferAttribute(new Float32Array(nr * 3), 3);
        indexAttr = new THREE.BufferAttribute(c.index.slice(), 1);
        geom.setAttribute("position", position);
        geom.setAttribute("normal", normal);
        geom.setAttribute("uv", new THREE.BufferAttribute(tmpl.uvR!, 2));
        smooth = { crease: c, src: pos, normal };
        updateCrease(c, pos, indexAttr.array as Uint16Array | Uint32Array, position.array as Float32Array, normal.array as Float32Array);
      } else {
        position = new THREE.BufferAttribute(pos, 3);
        indexAttr = new THREE.BufferAttribute(tmpl.index.slice(), 1);
        geom.setAttribute("position", position);
        // UVs: livery atlas on `livery` parts (shared per model; the vinyl overlay reads position only).
        geom.setAttribute("uv", new THREE.BufferAttribute(tmpl.uv, 2));
      }
      geom.setIndex(indexAttr);
      const mesh = new THREE.Mesh(geom, this.mat(material));
      mesh.name = `${this.carId}:${key}`;
      mesh.frustumCulled = false;
      if (material === "glass" || material.startsWith("lightbar_")) mesh.renderOrder = 1;
      this.root.add(mesh);
      const batch: Batch = { mesh, position, index: indexAttr, dirty: false, smooth };
      for (const p of parts) p.batch = batch;
      this.batches.push(batch);
      this.batchByKey.set(key, batch);
    }
  }

  /** Stop drawing a part (shattered glass, detached panel). */
  private hidePart(p: PartRT): void {
    p.hidden = true;
    p.mesh.visible = false;
    const b = p.batch;
    if (!b) return;
    // Collapse its triangles onto one vertex (degenerate: nothing rasterised).
    const idx = b.index.array as Uint16Array | Uint32Array;
    const first = idx[p.indexStart];
    idx.fill(first, p.indexStart, p.indexStart + p.def.indices.length);
    b.index.needsUpdate = true;
  }

  /** Hide a shattered glass region. */
  shatter(region: string): void {
    for (const p of this.parts) {
      if (p.def.region === region && p.def.kind === "glass") this.hidePart(p);
    }
  }

  /**
   * Re-skin every part from the current lattice nodes (chassis space, xyz per node) and the
   * panel states. `worldVel` (the car's world velocity, m/s) seeds detached-panel debris.
   */
  update(nodes: Float32Array, dt: number, worldVel?: THREE.Vector3): void {
    if (!this.ready) return;
    this.syncLivery();
    const states = panelStates(this.entity);
    // Same nodes and panel states as the last re-skin: every vertex would come out the same.
    if (nodes === this.skinnedNodes && sameFloats(states, this.states)) return;
    this.skinnedNodes = nodes;
    this.states = states;
    PanelBody.reskins++;
    this.frames.clear();
    for (let k = 0; k + PANEL_STRIDE <= this.states.length; k += PANEL_STRIDE) {
      const region = this.states[k];
      const state = this.states[k + 1];
      if (state === PANEL_STATE.unlatched || state === PANEL_STATE.hanging) {
        const tri = this.tri.get(region);
        if (tri) {
          let f = this.framePool.get(region);
          if (!f) {
            f = { r: new THREE.Matrix3(), rt: new THREE.Matrix3(), t: new THREE.Vector3() };
            this.framePool.set(region, f);
          }
          this.frames.set(region, fitFrame(this.restNodes, nodes, tri, f));
        }
      } else if (state === PANEL_STATE.detached && !this.spawned.has(region)) {
        this.spawned.add(region);
        if (dt > 0) this.spawnDebris(region, worldVel ?? new THREE.Vector3());
        else this.hideRegion(region);
      }
    }
    const rn = this.restNodes;
    // Panel state per region index (absent = no panel there, i.e. fixed structure).
    const stateOf = this.stateOf;
    stateOf.clear();
    for (let k = 0; k + PANEL_STRIDE <= this.states.length; k += PANEL_STRIDE) stateOf.set(this.states[k], this.states[k + 1]);
    const regionState = this.regionState;
    regionState.fill(-1);
    for (let k = 0; k + PANEL_STRIDE <= this.states.length; k += PANEL_STRIDE) regionState[this.states[k]] = this.states[k + 1];
    for (const p of this.parts) {
      if (p.hidden) continue;
      const f = p.region >= 0 ? this.frames.get(p.region) : undefined;
      const { rest, pos, nodes: ids, weights } = p;
      const state = stateOf.get(p.region);
      const free = state === PANEL_STATE.unlatched || state === PANEL_STATE.hanging;
      const sp = skinParams;
      if (f) {
        sp[SP_FRAME] = 1;
        const rt = f.rt.elements;
        const rm = f.r.elements;
        for (let k = 0; k < 9; k++) {
          sp[SP_RT + k] = rt[k];
          sp[SP_R + k] = rm[k];
        }
        sp[SP_T] = f.t.x;
        sp[SP_T + 1] = f.t.y;
        sp[SP_T + 2] = f.t.z;
      } else sp[SP_FRAME] = 0;
      const fold = p.fold;
      if (p.foldPack && this.chordBuf.length < p.foldPack.nc * CHORD_STRIDE) this.chordBuf = new Float64Array(p.foldPack.nc * CHORD_STRIDE);
      sp[SP_CHORDS] = p.foldPack ? chordFoldsInto(p.foldPack, p.foldMem, rn, nodes, sp, free, this.regionState, this.nodeRegions, this.states, this.chordBuf) : 0;
      sp[SP_ACROSS] = fold ? fold.across : 0;
      sp[SP_DIR] = fold ? fold.dir[0] : 0;
      sp[SP_DIR + 1] = fold ? fold.dir[1] : 0;
      sp[SP_DIR + 2] = fold ? fold.dir[2] : 0;
      sp[SP_REAR] = free ? FOLD_REAR_LIFT : 0;
      const r = skinOut;
      skinVertices(rest, pos, ids, weights, nodes, rn, sp, this.chordBuf, p.foldW, r);
      const maxDisp = r[0];
      const maxFold = r[1];
      const maxPull = r[2];
      p.maxDisp = Math.sqrt(maxDisp);
      p.maxFold = maxFold;
      p.maxPull = maxPull;
      if (p.batch) p.batch.dirty = true;
      else (p.mesh.geometry.getAttribute("position") as THREE.BufferAttribute).needsUpdate = true;
      if (p.def.kind === "light") {
        this.updateLight(p, stateOf);
        if (p.maxDisp > 1e-4) p.mesh.geometry.computeVertexNormals();
      }
    }
    for (const b of this.batches) {
      if (!b.dirty) continue;
      b.dirty = false;
      if (b.smooth) {
        const s = b.smooth;
        updateCrease(s.crease, s.src, b.index.array as Uint16Array | Uint32Array, b.position.array as Float32Array, s.normal.array as Float32Array);
        s.normal.needsUpdate = true;
        PanelBody.normalUpdates++;
      }
      b.position.needsUpdate = true;
    }
  }

  /**
   * A light lens breaks (dark, no glow) once the crush pushes it LIGHT_BREAK_M or the panel it
   * is bound to hangs or falls off. Stateless, so a repaired car gets its lights back.
   */
  private updateLight(p: PartRT, stateOf: Map<number, number>): void {
    let broken = p.maxDisp > LIGHT_BREAK_M;
    for (let k = 0; !broken && k < p.nodes.length; k++) {
      const s = stateOf.get(this.nodeRegions[p.nodes[k]]);
      broken = s === PANEL_STATE.hanging || s === PANEL_STATE.detached;
    }
    if (broken !== p.broken) {
      p.broken = broken;
      p.mesh.material = broken ? this.brokenLamp : this.mat(p.key);
    }
  }

  /** Per-part motion at the last update (tests): largest displacement, fold rise and leading-end pull-back, m. */
  partMotion(name: string): { disp: number; fold: number; pull: number; broken: boolean; hidden: boolean } | null {
    const p = this.parts.find((q) => q.def.name === name);
    return p ? { disp: p.maxDisp, fold: p.maxFold, pull: p.maxPull, broken: p.broken, hidden: p.hidden } : null;
  }

  /** Names of the body parts (mesh file and mods), tests. */
  partNames(): string[] {
    return this.parts.map((p) => p.def.name);
  }

  /** Largest vertex displacement of any part at the last update (tests: is the car dented), m. */
  maxDisp(): number {
    let m = 0;
    for (const p of this.parts) m = Math.max(m, p.maxDisp);
    return m;
  }

  /** Light lenses: name, broken, and whether they show the shared head/tail material. */
  lights(): { name: string; broken: boolean; material: THREE.Material; visible: boolean }[] {
    return this.parts
      .filter((p) => p.def.kind === "light")
      .map((p) => ({ name: p.def.name, broken: p.broken, material: p.mesh.material as THREE.Material, visible: !p.hidden && p.mesh.visible }));
  }

  private hideRegion(region: number): void {
    for (const p of this.parts) {
      if (p.region === region) this.hidePart(p);
    }
  }

  /**
   * Centre (chassis space, current dented shape) of `region`'s parts (any region: `null`) made
   * of `material` (`glass`, `headlight`, `taillight`), written to `out`. False when the mesh has
   * none (or is not loaded). Used by the crash effects (render/fx) to burst shards there.
   */
  materialCentre(region: string | null, material: PartMaterial, out: THREE.Vector3): boolean {
    let x = 0;
    let y = 0;
    let z = 0;
    let n = 0;
    for (const p of this.parts) {
      if ((region !== null && p.def.region !== region) || p.def.material !== material) continue;
      const pos = p.pos;
      for (let i = 0; i < pos.length; i += 3) {
        x += pos[i];
        y += pos[i + 1];
        z += pos[i + 2];
      }
      n += pos.length / 3;
    }
    if (n === 0) return false;
    out.set(x / n, y / n, z / n);
    return true;
  }

  /** Move a detached region's parts out of the car into world-space debris. */
  private spawnDebris(region: number, worldVel: THREE.Vector3): void {
    const parent = this.root.parent?.parent; // VehicleView.root → world group
    const car = this.root.parent;
    if (!parent || !car) return this.hideRegion(region);
    const group = new THREE.Group();
    group.position.copy(car.position);
    group.quaternion.copy(car.quaternion);
    const centroid = new THREE.Vector3();
    let count = 0;
    for (const p of this.parts) {
      if (p.region !== region || p.hidden) continue;
      const uv = p.own ? (p.mesh.geometry.getAttribute("uv").array as Float32Array) : dataOf(p.def).uv;
      const geom = debrisGeometry(p.rest, p.pos, p.def.indices, uv);
      // The batch's material for batched parts (re-materialed parts, a car's own copies).
      const drawn = (p.batch ? p.batch.mesh.material : p.mesh.material) as THREE.Material;
      const m = new THREE.Mesh(geom, debrisMaterial(p.def.kind, p.key, drawn, this.brokenLamp));
      m.name = p.def.name;
      m.userData.kind = p.def.kind;
      m.frustumCulled = false;
      group.add(m);
      for (let i = 0; i < p.pos.length; i += 3) {
        centroid.x += p.pos[i];
        centroid.y += p.pos[i + 1];
        centroid.z += p.pos[i + 2];
        count++;
      }
      this.hidePart(p);
    }
    if (count === 0) return;
    centroid.multiplyScalar(1 / count);
    // Pivot the debris about its own centre so it tumbles believably.
    for (const c of group.children) c.position.sub(centroid);
    group.position.add(centroid.clone().applyQuaternion(car.quaternion));
    parent.add(group);
    // Thrown outward from the car's centre, a little up; spin from the region index (deterministic).
    const out = new THREE.Vector3(centroid.x, centroid.y, 0).normalize().applyQuaternion(car.quaternion);
    const vel = worldVel.clone().addScaledVector(out, 1.5);
    vel.z += 1.2;
    const s = (region % 5) - 2;
    debris.push({ entity: this.entity, obj: group, vel, spin: new THREE.Vector3(1.5 + s * 0.4, -1.0 + s * 0.3, 0.8 - s * 0.2), age: 0 });
    while (debris.length > MAX_DEBRIS) debris.shift()?.obj.removeFromParent();
  }

  // ----- garage workshop (src/workshop): pick, hide and highlight parts by name ---------------

  /** The mesh part of a wheel-space mesh (null for other meshes). */
  wheelDef(m: THREE.Mesh): MeshPartJson | null {
    return this.wheelDefs.get(m) ?? null;
  }

  /** Called at the end of every applyStyle (cosmetic looks re-apply their material changes). */
  onStyled: (() => void) | null = null;
  private shiftCache = new Map<number, THREE.Vector3>();
  private shiftNodes: Float32Array | null = null;

  /**
   * Mean displacement (current − rest, chassis m) of region `name`'s lattice nodes at the last
   * re-skin: bolt-on parts ride along with a crushed bumper or a bent trunk. Zero before the
   * mesh is ready or for an unknown region.
   */
  regionShift(name: string, out: THREE.Vector3): THREE.Vector3 {
    out.set(0, 0, 0);
    const nodes = this.skinnedNodes;
    const r = this.regions.indexOf(name);
    if (!nodes || r < 0) return out;
    if (nodes !== this.shiftNodes) {
      this.shiftNodes = nodes;
      this.shiftCache.clear();
    }
    let c = this.shiftCache.get(r);
    if (!c) {
      c = new THREE.Vector3();
      let n = 0;
      const rest = this.restNodes;
      for (let i = 0; i < this.nodeRegions.length; i++) {
        if (this.nodeRegions[i] !== r) continue;
        c.x += nodes[i * 3] - rest[i * 3];
        c.y += nodes[i * 3 + 1] - rest[i * 3 + 1];
        c.z += nodes[i * 3 + 2] - rest[i * 3 + 2];
        n++;
      }
      if (n) c.divideScalar(n);
      this.shiftCache.set(r, c);
    }
    return out.copy(c);
  }

  /** Region `name`'s panel has come off the car (detached), so what is bolted to it goes too. */
  regionGone(name: string): boolean {
    const r = this.regions.indexOf(name);
    return r >= 0 && this.stateOf.get(r) === PANEL_STATE.detached;
  }

  /**
   * This car's own copy of a shared slot material (cosmetics recolour it without touching other
   * cars): every batch and part mesh drawn with the old material switches to the copy. The copy
   * keeps the greybox look of the original for applyStyle.
   */
  ownSlot(slot: MaterialJson): THREE.MeshStandardMaterial {
    return this.ownCopy(slot);
  }

  /** Mesh parts of this car with their centre (chassis metres); wheel parts are in hub space. */
  partDefs(): { def: MeshPartJson; centre: THREE.Vector3 }[] {
    const out = this.parts.map((p) => ({ def: p.def, centre: centreOf(p.def) }));
    for (const ps of [...this.wheelParts, ...this.hubParts])
      for (const m of ps) {
        const def = this.wheelDefs.get(m);
        if (def) out.push({ def, centre: centreOf(def) });
      }
    return out;
  }

  /** The visible part `ray` hits first, or null (body batches, lenses and wheel parts). */
  partAt(ray: THREE.Raycaster): MeshPartJson | null {
    return this.partHit(ray)?.def ?? null;
  }

  /** `partAt` with the hit distance along the ray. */
  partHit(ray: THREE.Raycaster): { def: MeshPartJson; distance: number } | null {
    const def = this.partHitDef(ray);
    return def && this.lastHitDistance !== null ? { def, distance: this.lastHitDistance } : null;
  }
  private lastHitDistance: number | null = null;

  private partHitDef(ray: THREE.Raycaster): MeshPartJson | null {
    const targets: THREE.Object3D[] = this.batches.map((b) => b.mesh);
    for (const p of this.parts) if (p.mesh.geometry !== NO_GEOMETRY && !p.hidden) targets.push(p.mesh);
    for (const ps of [...this.wheelParts, ...this.hubParts]) for (const m of ps) if (m.visible) targets.push(m);
    for (const b of this.batches) b.mesh.geometry.boundingSphere = null;
    const hit = ray.intersectObjects(targets, false)[0];
    this.lastHitDistance = hit?.distance ?? null;
    if (!hit) return null;
    const wheel = this.wheelDefs.get(hit.object as THREE.Mesh);
    if (wheel) return wheel;
    const batch = this.batches.find((b) => b.mesh === hit.object);
    if (!batch) return this.parts.find((p) => p.mesh === hit.object)?.def ?? null;
    const i = (hit.faceIndex ?? 0) * 3;
    const part = this.parts.find(
      (p) => p.batch === batch && i >= p.indexStart && i < p.indexStart + p.def.indices.length,
    );
    return part?.def ?? null;
  }

  /** Stop drawing every part `hide` picks (parts taken off in the workshop). */
  hideParts(hide: (def: MeshPartJson, centre: THREE.Vector3) => boolean): void {
    for (const p of this.parts) if (!p.hidden && hide(p.def, centreOf(p.def))) this.hidePart(p);
    for (const ps of [...this.wheelParts, ...this.hubParts])
      for (const m of ps) {
        const def = this.wheelDefs.get(m);
        if (def && hide(def, centreOf(def))) {
          m.visible = false;
          m.userData.wpHidden = true;
        }
      }
  }

  /** Glow over the parts `pick` selects (null clears it). Built from their current shape. */
  highlightParts(pick: ((def: MeshPartJson, centre: THREE.Vector3) => boolean) | null, colour = 0x39ff88): void {
    for (const m of this.glow) {
      m.geometry.dispose();
      m.removeFromParent();
    }
    this.glow = [];
    if (!pick) return;
    const material = (this.glowMat ??= new THREE.MeshBasicMaterial({
      color: colour,
      transparent: true,
      opacity: 0.45,
      depthTest: false,
      depthWrite: false,
    }));
    material.color.set(colour);
    for (const p of this.parts) {
      if (p.hidden || !pick(p.def, centreOf(p.def))) continue;
      const g = new THREE.BufferGeometry();
      g.setAttribute("position", new THREE.BufferAttribute(p.pos.slice(), 3));
      g.setIndex(new THREE.BufferAttribute(dataOf(p.def).index, 1));
      const m = new THREE.Mesh(g, material);
      m.renderOrder = 10;
      this.root.add(m);
      this.glow.push(m);
    }
    for (const ps of [...this.wheelParts, ...this.hubParts])
      for (const w of ps) {
        const def = this.wheelDefs.get(w);
        if (!def || !w.visible || !pick(def, centreOf(def))) continue;
        const m = new THREE.Mesh(w.geometry.clone(), material);
        m.renderOrder = 10;
        w.add(m);
        this.glow.push(m);
      }
  }

  dispose(): void {
    this.disposed = true;
    if (bodies.get(this.entity) === this) bodies.delete(this.entity);
    this.root.removeFromParent();
  }
}

/** A part's crumple binding (`FoldJson`) packed into typed arrays, built once per part model. */
interface FoldPack {
  nc: number;
  /** Per chord: fixed-end node, leading-end node. */
  chords: Int32Array;
  /** Lead node lists: group g is `leads[leadStart[g] .. leadStart[g + 1]]` (one per chord). */
  leads: Int32Array;
  leadStart: Int32Array;
  /** gain, max_m, pop_m, across. */
  scal: Float64Array;
}
function packFold(fold: FoldJson): FoldPack {
  const nc = fold.chords.length;
  const chords = new Int32Array(nc * 2);
  for (let c = 0; c < nc; c++) {
    chords[c * 2] = fold.chords[c][0];
    chords[c * 2 + 1] = fold.chords[c][1];
  }
  const ng = fold.leads.length;
  const leadStart = new Int32Array(ng + 1);
  for (let g = 0; g < ng; g++) leadStart[g + 1] = leadStart[g] + fold.leads[g].length;
  const leads = new Int32Array(leadStart[ng]);
  for (let g = 0; g < ng; g++) for (let j = 0; j < fold.leads[g].length; j++) leads[leadStart[g] + j] = fold.leads[g][j];
  return { nc, chords, leads, leadStart, scal: new Float64Array([fold.gain, fold.max_m, fold.pop_m, fold.across]) };
}

/** Scratch of `chordFoldsInto` (one re-skin at a time). */
const cfA = new Float64Array(3);
const cfB = new Float64Array(3);
const cfLead = new Float64Array(3);
const cfDl = new Float64Array(3);
const cfPivot = new THREE.Vector3();
const cfAxis = new THREE.Vector3();
const cfV = new THREE.Vector3();

/** Distance of node `i` from its rest position, m. */
function restOff(nodes: Float32Array, rn: Float32Array, i: number): number {
  return Math.hypot(nodes[i * 3] - rn[i * 3], nodes[i * 3 + 1] - rn[i * 3 + 1], nodes[i * 3 + 2] - rn[i * 3 + 2]);
}

/** Node `i` in the panel's own frame (`sp` SP_FRAME / SP_RT / SP_T; chassis space when
 * attached), into `out` (= `Vector3.applyMatrix3(rt)` of the node minus `t`). */
function chordLocal(nodes: Float32Array, sp: Float64Array, i: number, out: Float64Array): void {
  if (sp[SP_FRAME] === 0) {
    out[0] = nodes[i * 3];
    out[1] = nodes[i * 3 + 1];
    out[2] = nodes[i * 3 + 2];
    return;
  }
  const x = nodes[i * 3] - sp[SP_T];
  const y = nodes[i * 3 + 1] - sp[SP_T + 1];
  const z = nodes[i * 3 + 2] - sp[SP_T + 2];
  out[0] = sp[SP_RT] * x + sp[SP_RT + 3] * y + sp[SP_RT + 6] * z;
  out[1] = sp[SP_RT + 1] * x + sp[SP_RT + 4] * y + sp[SP_RT + 7] * z;
  out[2] = sp[SP_RT + 2] * x + sp[SP_RT + 5] * y + sp[SP_RT + 8] * z;
}

/**
 * Lead node `i` as if its panel were still attached, into `out`: a hanging panel's node
 * rotated back by its hang angle about its pivot (the sim captures the hanging pose at angle
 * 0, so this is the crushed pose it was released in); false once its panel fell off
 * (tools/assets `lead_pos`).
 */
function leadPos(i: number, nodes: Float32Array, regionState: Int8Array, nodeRegions: Uint8Array, s: Float32Array, out: Float64Array): boolean {
  const r = nodeRegions[i];
  const st = regionState[r];
  if (st === PANEL_STATE.detached) return false;
  out[0] = nodes[i * 3];
  out[1] = nodes[i * 3 + 1];
  out[2] = nodes[i * 3 + 2];
  if (st !== PANEL_STATE.hanging) return true;
  for (let k = 0; k + PANEL_STRIDE <= s.length; k += PANEL_STRIDE) {
    if (s[k] !== r) continue;
    cfPivot.set(s[k + 4], s[k + 5], s[k + 6]);
    cfAxis.set(s[k + 7], s[k + 8], s[k + 9]);
    cfV.set(out[0], out[1], out[2]).sub(cfPivot).applyAxisAngle(cfAxis, -s[k + 2]).add(cfPivot);
    out[0] = cfV.x;
    out[1] = cfV.y;
    out[2] = cfV.z;
    return true;
  }
  return true;
}

/**
 * Fold values per chord of a crumpling part (mirrors tools/assets `skin::chord_folds`): the
 * larger of the own chord loss (panel frame, from `sp`) and the lead push (chassis space, a
 * hanging bumper's nodes taken back to their attached pose), times the visual gain, ratcheted
 * in the part's crumple memory `foldMem`. Written into `out` (CHORD_STRIDE floats per chord);
 * returns the chord count. Typed arrays only and warmed with the skinning (`warmSkinVertices`):
 * as a method reading the fold JSON it ran a few times a frame and never left the tier where
 * every float operation allocates (~10 KB a frame, allocation pass 2026-10-20).
 */
function chordFoldsInto(
  fp: FoldPack,
  foldMem: Float32Array,
  rn: Float32Array,
  nodes: Float32Array,
  sp: Float64Array,
  free: boolean,
  regionState: Int8Array,
  nodeRegions: Uint8Array,
  states: Float32Array,
  out: Float64Array,
): number {
  const nc = fp.nc;
  const ch = fp.chords;
  const leads = fp.leads;
  const ls = fp.leadStart;
  const gain = fp.scal[0];
  const maxM = fp.scal[1];
  const popM = fp.scal[2];
  const across = fp.scal[3] | 0;
  let atRest = true;
  for (let c = 0; atRest && c < nc; c++) atRest = restOff(nodes, rn, ch[c * 2]) <= FOLD_REST_EPS_M && restOff(nodes, rn, ch[c * 2 + 1]) <= FOLD_REST_EPS_M;
  for (let j = 0; atRest && j < leads.length; j++) atRest = restOff(nodes, rn, leads[j]) <= FOLD_REST_EPS_M;
  if (atRest) foldMem.fill(0);
  const la_ = cfA;
  const lb = cfB;
  const at = cfLead;
  const dl = cfDl;
  for (let c = 0; c < nc; c++) {
    const a = ch[c * 2];
    const b = ch[c * 2 + 1];
    const ru0 = rn[b * 3] - rn[a * 3];
    const ru1 = rn[b * 3 + 1] - rn[a * 3 + 1];
    const ru2 = rn[b * 3 + 2] - rn[a * 3 + 2];
    const la = Math.max(Math.hypot(ru0, ru1, ru2), 1e-4);
    const o = c * CHORD_STRIDE;
    out[o + 4] = ru0 / la;
    out[o + 5] = ru1 / la;
    out[o + 6] = ru2 / la;
    chordLocal(nodes, sp, a, la_);
    chordLocal(nodes, sp, b, lb);
    const own = la - Math.hypot(lb[0] - la_[0], lb[1] - la_[1], lb[2] - la_[2]);
    let pushLatch = 0;
    for (let k = 0; k < 3; k++) pushLatch -= (lb[k] - rn[b * 3 + k] - (la_[k] - rn[a * 3 + k])) * out[o + 4 + k];
    dl[0] = 0;
    dl[1] = 0;
    dl[2] = 0;
    let n = 0;
    for (let j = ls[c]; j < ls[c + 1]; j++) {
      const l = leads[j];
      if (!leadPos(l, nodes, regionState, nodeRegions, states, at)) continue;
      for (let k = 0; k < 3; k++) dl[k] += at[k] - rn[l * 3 + k];
      n++;
    }
    let pushLead = pushLatch;
    if (n > 0) {
      pushLead = 0;
      for (let k = 0; k < 3; k++) pushLead -= (dl[k] / n - (nodes[a * 3 + k] - rn[a * 3 + k])) * out[o + 4 + k];
    }
    const eff = Math.max(gain * Math.max(own, pushLead), foldMem[c * 2]);
    const extra = Math.max(pushLead - pushLatch, 0, foldMem[c * 2 + 1]);
    foldMem[c * 2] = eff;
    foldMem[c * 2 + 1] = extra;
    out[o] = rn[b * 3 + across];
    out[o + 1] = Math.min(FOLD_SPLIT * foldHeight(la, eff), maxM);
    out[o + 2] = Math.min(extra, FOLD_PULL_MAX * la);
    out[o + 3] = free ? popM : 0;
  }
  return nc;
}

/** Three nodes of `region` spanning the largest triangle (rest pose). */
function spanTriangle(rest: Float32Array, regions: Uint8Array, region: number): [number, number, number] {
  const ids: number[] = [];
  for (let i = 0; i < regions.length; i++) if (regions[i] === region) ids.push(i);
  let best: [number, number, number] = [ids[0] ?? 0, ids[1] ?? 0, ids[2] ?? 0];
  let area = -1;
  const a = new THREE.Vector3();
  const b = new THREE.Vector3();
  const c = new THREE.Vector3();
  for (let i = 0; i < ids.length; i++)
    for (let j = i + 1; j < ids.length; j++)
      for (let k = j + 1; k < ids.length; k++) {
        a.fromArray(rest, ids[i] * 3);
        b.fromArray(rest, ids[j] * 3).sub(a);
        c.fromArray(rest, ids[k] * 3).sub(a);
        const ar = b.cross(c).lengthSq();
        if (ar > area) {
          area = ar;
          best = [ids[i], ids[j], ids[k]];
        }
      }
  return best;
}

/** Orthonormal frame of a node triangle as columns, into `out` (scratch vectors below). */
function triFrame(p: Float32Array, [i, j, k]: [number, number, number], out: { m: THREE.Matrix3; o: THREE.Vector3 }): void {
  const o = out.o.fromArray(p, i * 3);
  const e1 = tfE1.fromArray(p, j * 3).sub(o).normalize();
  const c = tfC.fromArray(p, k * 3).sub(o);
  const e3 = tfE3.crossVectors(e1, c).normalize();
  const e2 = tfE2.crossVectors(e3, e1);
  out.m.set(e1.x, e2.x, e3.x, e1.y, e2.y, e3.y, e1.z, e2.z, e3.z);
}
const tfE1 = new THREE.Vector3();
const tfC = new THREE.Vector3();
const tfE2 = new THREE.Vector3();
const tfE3 = new THREE.Vector3();
const tfA = { m: new THREE.Matrix3(), o: new THREE.Vector3() };
const tfB = { m: new THREE.Matrix3(), o: new THREE.Vector3() };
const tfAt = new THREE.Matrix3();
const tfV = new THREE.Vector3();

/** Rigid transform taking the triangle's rest frame to its current frame, into `out` (no
 * allocation: it runs for every free panel on each re-skin). */
function fitFrame(rest: Float32Array, cur: Float32Array, tri: [number, number, number], out: Frame): Frame {
  triFrame(rest, tri, tfA);
  triFrame(cur, tri, tfB);
  const r = out.r.copy(tfB.m).multiply(tfAt.copy(tfA.m).transpose());
  out.t.copy(tfB.o).sub(tfV.copy(tfA.o).applyMatrix3(r));
  out.rt.copy(r).transpose();
  return out;
}
